/* 身為魚販 */
(window.TB_LESSONS = window.TB_LESSONS || []).push(["身為魚販", {"lesson": [{"no": "1-0", "sec": "第1節", "time": "", "kind": "cover", "title": "第 1 節　走進魚販的日常", "sub": "認識作者與工作內容，讀懂作者的處境", "teach": "本節 50 分鐘。目標：先用課文證據理解，<b>不急著評價</b>。<br>提醒自己：學生說「他很孝順」「他很辛苦」時，要追問「課文哪裡看得出來」。"}, {"no": "1-1", "sec": "第1節", "time": "0–5′", "kind": "ask", "title": "如果你要在市場賣魚，<br>一天可能會遇到哪些事？", "hint": "先不用判斷這份工作好不好，先想像一天的樣子。", "teach": "開場照念：「今天要讀的文章叫〈身為魚販〉。先不急著判斷這份工作好不好。我們先想想：如果你要在市場賣魚，一天可能會遇到哪些事情？」<br><br><b>沒反應時給提示：</b>早起、搬運、整理魚貨／氣味、環境、體力／面對客人、價格與生意／工作時間與休息<br><br><b>收束：</b>「這些是我們<b>想像</b>的魚販工作。等一下讀課文時，請分辨：哪些是我們原本就想到的，哪些是<b>作者讓我們看見的細節</b>。」"}, {"no": "1-2", "sec": "第1節", "time": "5–12′", "kind": "board", "title": "今天的閱讀任務", "board": ["<b>①</b> 工作細節　——　作者實際做了哪些事？", "<b>②</b> 生活處境　——　他面對哪些現實？", "<b>③</b> 作者的感受　——　他怎麼想？"], "teach": "先介紹作者（可切到「作者·課本」頁）：林楷倫，魚販第三代，現為專職魚販、作家。<br><br>照念：「讀這篇文章時，先不要急著找中心思想。我們先做一件比較具體的事：把作者寫到的<b>工作細節</b>圈起來。」<br><br><b>關鍵提醒（先講，之後一直用）：</b>「我們今天先不急著把作者歸類成『很孝順』或『很偉大』。這些是<b>評價</b>；閱讀時，我們要先找到他<b>經歷了什麼</b>。」"}, {"no": "1-3", "sec": "第1節", "time": "12–25′", "kind": "task", "title": "第一次閱讀：圈出工作細節", "task": ["圈出<b>作者在魚攤上實際做了哪些事</b>", "旁邊簡短註記：工作動作／感官細節／與他人互動／工作環境"], "hint": "答案盡量回到文章裡，不要只寫「很辛苦」。", "teach": "分段朗讀，逐段提示：<br>· 「這一段寫到哪些<b>具體</b>工作？」<br>· 「哪個詞句讓你感覺到工作的辛苦或繁複？」<br>· 「這是作者<b>直接說明</b>，還是透過<b>動作、場景</b>讓我們看見？」<br><br><b>巡視時問：</b>「你圈的是工作<b>動作</b>，還是作者的<b>感受</b>？」<br><br><span class='ls-warn'>建議切到「◉第1部分～第2部分」邊讀邊點注釋。</span>"}, {"no": "1-4", "sec": "第1節", "time": "12–25′", "kind": "quote", "title": "這一段，先停下來", "quote": "阿公拿起冷凍與現流的白鯧，教我看背上的藍色與鱗片上的微微虹光分辨鮮度，教我從魚鰭魚尾分辨不同品種的白鯧：<b>魚鰭長且魚尾如剪刀的，是正鯧；體色偏灰、魚鰭短的是暗鯧；魚鰭、魚尾短短，鰭邊形狀如流蘇是斗鯧。</b>他問我哪種好吃，我說正鯧，暗鯧與斗鯧偏軟。<b>阿公稱讚嘴刁的我。</b>", "ask": ["這段在寫<b>魚</b>，還是在寫<b>人</b>？", "阿公是在<b>考</b>他，還是在<b>教</b>他？"], "teach": "這段看起來是魚貨知識，其實是<b>全文少數他被肯定的時刻</b>。<br><br>要帶到：<br>· 這是<b>師徒關係</b>，不是父子壓力。<br>· 他在魚攤上被稱讚「嘴刁」，在學校卻要遮掩身分——<b>兩個世界的落差</b>從這裡開始。<br><br>接下去就是「阿公說賣魚要學，學一輩子」，可以連著講。"}, {"no": "1-5", "sec": "第1節", "time": "25–35′", "kind": "ask", "title": "作者為什麼會做這份工作？", "points": ["文中有哪些<b>生活或家庭</b>方面的限制？", "這些限制如何影響作者的選擇？", "作者的選擇，是完全不受影響的<b>自由選擇</b>嗎？"], "hint": "換一種顏色的筆，圈出與家庭、責任、期許、個人想法有關的內容。", "teach": "照念：「我們不是要替作者貼標籤，也不是要猜測課文沒有寫的事情。請<b>只根據文本</b>，找出作者面對的現實條件。」<br><br><b>學生可能回答：</b>「不是，家裡有需要。」「他有自己的想法，但也要考慮家庭。」<br><br><b>接話：</b>「這些都可以討論。請注意：我們不是說有家庭責任就一定要接班，也不是說作者不應該有自己的想法。我們要看懂的是：作者的選擇<b>是在什麼條件下形成的</b>。」"}, {"no": "1-6", "sec": "第1節", "time": "35–45′", "kind": "table", "title": "整理：作者的處境", "cols": ["文本線索", "顯示的處境", "我的理解"], "rows": [["課文中的詞句或事件", "具體情況", "這讓我看見……"]], "hint": "請寫在課本空白處，不用另外抄。", "teach": "<b>巡視時的三句追問（最重要）：</b><br>· 「你說他有責任感，<b>課文哪裡</b>看得出來？」<br>· 「你說他不想做，是<b>從哪個地方</b>判斷的？」<br>· 「你能不能把『他很無奈』改成『他<b>因為</b>＿＿，<b>所以</b>＿＿』？」<br><br>目標：把籠統的「很累」「很可憐」改成<b>有文本依據</b>的說明。"}, {"no": "1-7", "sec": "第1節", "time": "45–50′", "kind": "exit", "title": "下課前，口頭回答兩句", "lines": ["今天我從課文中看見魚販工作的一個<b>具體細節</b>：＿＿＿＿", "我還想知道作者對這份工作的哪一件事：＿＿＿＿"], "teach": "不收單，口頭點 3–4 位即可。<br><br><b>收束：</b>「今天我們先認識魚販工作的實際內容，也開始理解作者的處境。下一節會繼續追蹤他的心情怎麼變化。」"}, {"no": "2-0", "sec": "第2節", "time": "", "kind": "cover", "title": "第 2 節　從經驗到重新理解", "sub": "梳理作者的情感變化，完成課文教學", "teach": "本節結束就把課文教完。目標：讓學生用<b>文本證據</b>說明作者的變化。<br><br><span class='ls-warn'>特別注意：這篇<b>沒有乾淨的轉折</b>。他沒有想通，只是不再等了。學生若說「我覺得沒有明顯轉折」，只要說明理由就給過。</span>"}, {"no": "2-1", "sec": "第2節", "time": "0–5′", "kind": "ask", "title": "回顧：作者成為魚販，<br>是因為他一開始就喜歡嗎？", "hint": "翻出上節的註記，找出你寫的其中一個因素。", "teach": "照念：「上一節我們先看見魚販工作的具體樣貌。今天要追問：<b>作者怎麼看待這段經驗？他的想法有沒有變化？</b>」<br><br>請 2–3 位學生分享一個文本細節。"}, {"no": "2-2", "sec": "第2節", "time": "5–18′", "kind": "task", "title": "標記情感與想法", "task": ["作者<b>當時的感受</b>", "讓感受<b>改變</b>的事件或觀察", "作者<b>後來的理解</b>"], "hint": "不要只圈「他很難過」「他很努力」，要找出：他當時怎麼想？為什麼這樣想？", "teach": "<b>逐段提問：</b><br>· 「作者在哪裡表達了<b>明確</b>感受？」<br>· 「哪個事件或細節可能是理解改變的關鍵？」<br>· 「這個改變是<b>突然</b>發生，還是<b>逐步</b>形成？」<br><br><b>引導：</b>「有些人的想法改變，不一定是突然想通，而可能是經歷了很多事，慢慢改變看法。」"}, {"no": "2-3", "sec": "第2節", "time": "5–18′", "kind": "key3", "title": "三個關鍵句", "teach": "這三句是本課核心，建議一句一句停下來問。<br>課文頁上這三句都有<b>綠色底線</b>，點「句意」可展開說明。"}, {"no": "2-4", "sec": "第2節", "time": "18–30′", "kind": "table", "title": "小組整理：作者的情感變化", "cols": ["階段", "作者的想法／感受", "對應文本線索"], "rows": [["起初", "", ""], ["接觸現實後", "", ""], ["<b>最關鍵的時刻</b>", "", ""], ["後來的理解", "", ""]], "hint": "如果組員理解不同，可以先把不同答案都寫下來，再回到文本討論哪一種更有根據。", "teach": "<span class='ls-warn'>第三格刻意叫「<b>最關鍵的時刻</b>」而不是「轉折」——因為這篇的力量恰恰在於沒有乾淨的轉折。若逼學生填「轉折」，容易逼出「後來他想開了」這種簡化答案。</span><br><br><b>報告後追問：</b><br>· 「你們說作者改變了，改變的是<b>態度、做法，還是理解</b>？」<br>· 「他後來重新看待工作，是否代表<b>過去的辛苦就消失了</b>？」<br>· 「我們能不能<b>同時</b>承認他有責任，也承認他有自己的想法？」"}, {"no": "2-5", "sec": "第2節", "time": "30–40′", "kind": "ask", "title": "作者把魚賣得很好，<br>這代表他已經<u>接受</u>這份工作了嗎？", "points": ["「把工作做好」和「必須忍受所有不合理」有什麼不同？", "一個人的工作價值，只能由收入、地位或別人的眼光決定嗎？"], "teach": "<span class='ls-warn'>主問題刻意貼著文本問。比「什麼工作才有價值」更好，因為它讓學生發現「<b>做得好</b>」和「<b>想做</b>」可以<b>不同時成立</b>——這才是這篇的難處。</span><br><br><b>收束照念：</b>「文章讓我們理解一段工作經驗，但不代表每個人都必須接受同一種人生選擇。尊重工作，也可以同時思考勞動條件、公平與個人選擇。」<br><br>「一個人可以對工作有不喜歡的地方，也可以在工作中學到能力。這兩件事<b>不一定互相矛盾</b>。」"}, {"no": "2-6", "sec": "第2節", "time": "40–47′", "kind": "exit", "title": "短答練習", "lines": ["作者對這段魚販經驗的理解<b>有何變化</b>？", "請引用或概述<b>一個文本細節</b>，說明你的看法。"], "hint": "句型：我認為作者＿＿。因為課文提到＿＿。這讓我想到＿＿。不過，我也想知道＿＿。", "teach": "<b>評量重點：</b><br>① 有回答作者想法或感受的<b>變化</b><br>② 有<b>文本細節</b>作為依據<br>③ 說明「細節如何支持理解」，而非只抄句子"}, {"no": "2-7", "sec": "第2節", "time": "47–50′", "kind": "bridge", "title": "課文到這裡結束", "sub": "下一節：把「用細節呈現經驗」變成自己的寫作方法", "teach": "照念：「到這裡，我們已經把課文讀完，也整理了作者如何從具體經驗形成理解。下一節<b>不再繼續講課文</b>，而是把閱讀時學到的『用細節呈現經驗』轉成自己的寫作方法。」<br><br>「作文不要求大家寫魚販，也不要求寫家庭接班。可以從打工、實習、課業、友情或其他經驗中，挑一件真正記得的事來寫。」"}, {"no": "3-0", "sec": "第3節", "time": "", "kind": "cover", "title": "第 3 節　把感受寫成文章", "sub": "從生活經驗取材，練習把一件事寫清楚、寫具體", "teach": "本節不分析課文，改用課文<b>當寫作範例</b>——學生剛讀過，接得上。<br><br><b>本節底線：</b>不強迫寫家庭隱私、不強迫正向結局、不要求華麗修辭。"}, {"no": "3-1", "sec": "第3節", "time": "0–5′", "kind": "board", "title": "作文不是只寫感想", "board": ["事件　→　細節　→　感受／想法　→　意義"], "hint": "作文不是只有文筆好的人才寫得出來。今天先學：把一件事說清楚。", "teach": "照念：「今天不是要大家寫一篇很偉大的人生故事。只要選一件你曾經有不同看法、後來多理解了一點的事，就可以寫。」<br><br>「你<b>不必寫家庭或私人隱私</b>，也<b>不必把結尾寫得很正面</b>。真實、具體，比勉強感人更重要。」"}, {"no": "3-2", "sec": "第3節", "time": "5–12′", "kind": "menu", "title": "選素材：想一件你到現在還記得的事", "items": ["打工", "實習", "考試或考證照", "分組報告", "社團或比賽", "友情或誤會", "生活責任", "一次失敗或重新嘗試"], "hint": "不一定是大事，也不一定是很感人的事。先寫下兩件，暫時不用分享。", "teach": "<b>提示問題：</b><br>· 我原本怎麼看待這件事？<br>· 發生了什麼具體事件？<br>· 哪個瞬間讓我開始有不同想法？<br>· 我現在的看法有沒有保留或矛盾？"}, {"no": "3-3", "sec": "第3節", "time": "12–20′", "kind": "filter", "title": "篩選：問自己三個問題", "qs": ["我記得這件事<b>大致怎麼發生</b>嗎？", "其中有沒有一個<b>特別重要的時刻</b>？", "這件事有沒有讓我產生<b>感受、疑問或想法</b>？"], "hint": "三題都很難答就換一件。作文不是挑最大的人生事件，而是挑你<b>有內容可以寫</b>的事。", "teach": "學生選定後，請他們先回答：<br>· 事件發生的時間／地點<br>· 當時有哪些人<br>· 我做了什麼／看見什麼<br>· 當時的感受<br>· 後來想法改變的原因<br><br><b>巡視時：</b>「如果只有『我很感動』或『我很生氣』，讀者還不知道發生什麼事。試著補上一個<b>看得見、聽得到或做得到</b>的細節。」"}, {"no": "3-4", "sec": "第3節", "time": "20–30′", "kind": "demo1", "title": "示範①：課文怎麼寫「感受」", "teach": "這一頁直接投影給學生看。<br><br><b>可以這樣問：</b>「這四句裡，有出現『丟臉』『開心』『失望』這些詞嗎？沒有。那我們怎麼知道？——因為他寫了<b>動作</b>、寫了<b>對話</b>、寫了<b>並排的兩句話</b>。」"}, {"no": "3-5", "sec": "第3節", "time": "20–30′", "kind": "board", "title": "五個追問：把感受變成畫面", "board": ["① 什麼時候？", "② 在哪裡？", "③ 正在做什麼？", "④ 誰說了什麼／發生什麼？", "⑤ 我做了什麼反應？"], "hint": "不要只告訴讀者你有什麼感受，要寫出<b>讓你產生感受的畫面</b>。", "teach": "示範改寫：<br><br><b>原句：</b>我打工很累，也很委屈。<br><br><b>改寫：</b><span class='ls-good'>打烊後，我把最後一張桌子擦完，抬頭看了一眼牆上的時鐘。手機跳出同學聚餐的照片，我打了「你們玩得開心」，又把手機放回口袋。</span><br><br><b>解說：</b>「這段<b>沒有直接說『我很委屈』</b>，但我們可以從打烊時間、同學聚餐的照片，以及把手機放回口袋的動作，理解人物當時的感受。」"}, {"no": "3-6", "sec": "第3節", "time": "20–30′", "kind": "demo2", "title": "示範②：常見卡關怎麼改", "teach": "學生卡住時<b>直接翻到這頁</b>，找對應那一列念給他聽。<br><br><b>共同原則：</b>不要刪掉感受詞，而是<b>在感受詞前面補一個畫面</b>。學生比較不會覺得「我寫的被否定了」。"}, {"no": "3-7", "sec": "第3節", "time": "30–40′", "kind": "write", "title": "動筆：只寫一個最記得的時刻", "spec": ["先用幾個詞回答五個追問", "再把答案組成一段話", "<b>100–200 字</b>就好"], "hint": "先不要寫整篇作文。", "teach": "<b>巡視檢核：</b>① 具體事件？② 至少一個可感知細節？③ 呈現當時感受？④ 避免空泛結論？<br><br><b>逐步協助：</b><br>· 寫「我很緊張」→「你緊張時，身體或動作有什麼變化？」<br>· 寫「他罵我」→「他說了什麼？不記得原話可寫大意。當時你在做什麼？」<br>· 寫「後來我很難過」→「事情結束後你做了什麼？沉默、離開，還是繼續做事？」"}, {"no": "3-8", "sec": "第3節", "time": "40–45′", "kind": "peer", "title": "兩人互讀：回饋三句", "lines": ["我最<b>看得見</b>的畫面是＿＿＿＿", "我想<b>更了解</b>的地方是＿＿＿＿", "你可以再補一個＿＿＿＿的細節"], "hint": "回饋針對文章，不評論同學的人生選擇，也不追問對方不想公開的事。", "teach": "照念：「如果讀者看不懂事情發生什麼，<b>不代表你不會寫</b>，而是提醒你哪裡需要補充。修改就是讓讀者更容易理解。」<br><br><b>不要求上台朗讀</b>。"}, {"no": "3-9", "sec": "第3節", "time": "45–50′", "kind": "outline", "title": "作文提綱", "topic": "《那一次，我重新看待＿＿＿＿》", "rows": [["起", "我<b>原本</b>如何看待＿＿", "以前我一直以為＿＿。"], ["承", "<b>發生</b>了什麼事？交代必要背景", "那天＿＿，事情開始＿＿。"], ["轉", "描寫<b>關鍵場景</b>，呈現想法變化", "我記得最清楚的是＿＿。"], ["合", "我<b>現在</b>如何理解這件事", "現在再想到這件事，我＿＿。"]], "teach": "<b>最後提醒照念：</b>「作文不一定要寫成『我終於明白一切』。你可以寫自己改變了，<b>也可以寫自己仍然不理解</b>；只要把事件寫清楚，並說明你的想法，就有寫作內容。」<br><br><b>課後作業：</b>擴寫成 300–500 字短文（能力佳者 500–800 字）。"}, {"no": "3-10", "sec": "第3節", "time": "", "kind": "fill", "title": "題目怎麼填？", "teach": "學生填不出空格時投影這頁。<br><br><b>關鍵提醒：</b>「重新看待」<b>不等於</b>「變喜歡」。跟課文一樣——作者沒有變得愛賣魚，他只是不再等一個不會醒的人。"}, {"no": "3-11", "sec": "第3節", "time": "", "kind": "rubric", "title": "評分重點", "teach": "<b>評分原則：</b>先評內容是否清楚、具體，再看語句修飾；<b>不把「最後一定要感謝、接受或成長」當成標準答案。</b>"}],"workbook": {"title": "習作Ａ　第一課　身為魚販", "sections": [{"kind": "table", "head": "壹 基礎認知站　一、字音探勘隊（每題 1 分，共 8 分）", "cols": ["", "字音", "詞語", "", "字音", "詞語"], "rows": [["1", "<span class='wk-a'>ㄨˇ</span>", "「摀」住口鼻", "2", "<span class='wk-a'>ㄆㄠˊ</span>", "「刨」鱗殺肚"], ["3", "<span class='wk-a'>ㄔㄥˋ</span>", "電子磅「秤」", "4", "<span class='wk-a'>ㄌㄟ</span>", "「勒」緊了腿"], ["5", "<span class='wk-a'>ㄈㄨˊ</span>", "掙脫束「縛」", "6", "<span class='wk-a'>ㄓㄨㄛˊ</span>", "黏「著」劑"], ["7", "<span class='wk-a'>ㄆㄡˇ</span>", "魚類解「剖」", "8", "<span class='wk-a'>ㄔㄥˋ</span>", "「稱」職"]]}, {"kind": "table", "head": "二、字形領航員（每題 1 分，共 8 分）", "cols": ["", "字形", "詞語", "", "字形", "詞語"], "rows": [["1", "<span class='wk-a'>頹</span>", "「ㄊㄨㄟˊ」敗不堪", "2", "<span class='wk-a'>嘈</span>", "聲音「ㄘㄠˊ」雜"], ["3", "<span class='wk-a'>辨</span>", "魚類「ㄅㄧㄢˋ」識", "4", "<span class='wk-a'>販</span>", "「ㄈㄢˋ」售物品"], ["5", "<span class='wk-a'>蕩</span>", "空「ㄉㄤˋ」無人", "6", "<span class='wk-a'>徒</span>", "年輕學「ㄊㄨˊ」"], ["7", "<span class='wk-a'>嵌</span>", "鑲「ㄑㄧㄢ」寶石", "8", "<span class='wk-a'>嚮</span>", "心神「ㄒㄧㄤˋ」往"]]}, {"kind": "table", "head": "三、字義飛行傘（每題 2 分，共 8 分）", "cols": ["", "詞語", "答案", "", "詞語", "答案"], "rows": [["1", "「稱」讚", "<span class='wk-a'>B</span>", "2", "「稱」職", "<span class='wk-a'>A</span>"], ["3", "「稱」重量", "<span class='wk-a'>D</span>", "4", "「稱」兄道弟", "<span class='wk-a'>C</span>"]], "note": "請選出下列「　」內的正確字義代號。<br>參考選項：(A)適合　(B)讚頌、讚譽　(C)叫、叫做　(D)用秤計量輕重"}, {"kind": "table", "head": "四、文學常識解碼（每格 1 分，共 6 分）", "cols": ["項目", "內容"], "rows": [["寫作歷程", "1 作者從國中時便開始賣魚，展開「老師要他爭氣、同學嫌他腥臭」的生活<br>2 為幫忙家計、替（1 <b class='wk-a'>父親</b>）償還賭債而中斷學業，成為第三代魚販。對他而言，賣魚是（2 <b class='wk-a'>不得已</b>）的選擇<br>3 成家後，為了不讓妻小受到牽連，而脫離原生家庭。現在他努力賣魚，撐起家中經濟<br>4 林楷倫將成長歷程的所見所聞所感寫下來，現為專職魚販、作家"], ["寫作風格", "1 散文風格（3 <b class='wk-a'>寫實</b>）又富戲劇張力，帶有（4 <b class='wk-a'>小說</b>）筆法<br>2 內容兼具賣魚知識和生命自省，生動敘寫人情事理"], ["作品", "曾獲得林榮三文學獎、《時報》文學獎、臺北文學獎、臺中文學獎等。著有散文集（5 <b class='wk-a'>《偽魚販指南》</b>）、短篇小說集（6 <b class='wk-a'>《雪卡毒》</b>）等"]], "note": "請依據你對林楷倫的認識，完成下列表格（　）中的內容。"}, {"kind": "quiz", "head": "五、綜合理解練習（每題 5 分，共 40 分）", "items": [{"n": 1, "q": "下列「　」內的字，何者讀音相同？", "ans": "C", "opts": [["A", "「勒」緊了腿／敲詐「勒」索", "ㄌㄟ／ㄌㄜˋ。"], ["B", "「摀」住耳朵／停靠船「塢」", "ㄨˇ／ㄨˋ。"], ["C", "人生「嚮」導／不知去「向」", "ㄒㄧㄤˋ。"], ["D", "「稱」心如意／大力「稱」讚", "ㄔㄥˋ／ㄔㄥ。"]]}, {"n": 2, "q": "在〈身為魚販〉一文中，作者承襲家庭事業，成為第三代魚販，如此人生經歷可以用下列哪個成語形容？", "ans": "A", "opts": [["A", "克紹箕裘", "比喻能繼承家業。箕裘，指父業。"], ["B", "一傅眾咻", "比喻學習受到干擾，成效不佳，或環境對人的影響很大。"], ["C", "風行草偃", "比喻在上位者以德化民。"], ["D", "春風化雨", "比喻師長和藹親切的教育。"]]}, {"n": 3, "q": "林楷倫在〈身為魚販〉一文中，書寫自身的生命省思。下列何者是他成為魚販的原因？<br>(甲)幫忙負擔家計　(乙)相關科系畢業　(丙)償還父親賭債　(丁)鍾愛賣魚生活", "ans": "C", "opts": [["A", "(甲)(乙)", ""], ["B", "(乙)(丁)", ""], ["C", "(甲)(丙)", "(乙)林楷倫曾就讀中臺科技大學五專部醫事技術系、銘傳大學、朝陽科技大學傳播藝術系、東海大學社會系與交通大學社會與文化研究所。(丁)由文中「因為我不想當魚販，不想多踏一步，踏到殺魚的臺前，拿起魚刨鱗，剪刀剪開魚的皮肉。這些不想，我沒有說出口」、「賣魚賣雞賣肉不太會成為志願，也非我志向，非我所願」可知為非。"], ["D", "(乙)(丙)", ""]]}, {"n": 4, "q": "依據下文，何者敘述最適當？<div class='aq-sub'>　　現在我會吃冷凍的白鯧了，我會輕輕的夾給兒女和自己。我們都吃過現流的白鯧，所以知道冷凍白鯧不好吃。<br>　　變成稱職的魚販之前，我學會了什麼工作令我厭惡，同時學會了什麼令我嚮往。既然不愛的、討厭的都能做好，那還有什麼不能做呢？我這麼想。<br>　　沒有出生就會賣魚的人。沒有什麼東西，不用學一輩子。<br>　　身為一名魚販，我很努力，很努力了。</div>", "ans": "B", "opts": [["A", "因為家裡經濟不好，作者只能採買白鯧餵養兒女", "並無此說法。"], ["B", "作者不願賣魚但身不由己，討厭的工作也要做好", ""], ["C", "賣魚是令作者嚮往的工作，所以他願意學一輩子", "賣魚不是作者志願，但因家庭原因只得賣魚，因此體悟到再不喜歡的工作也須做好。"], ["D", "作者自認是還不夠努力的魚販，因此達不到標準", "作者接受自己是個魚販，重複「很努力」，表示對這個身分的肯定。"]]}, {"n": 5, "q": "〈身為魚販〉中，作者父親對於兒子讀書或賣魚的看法，下列敘述何者正確？", "ans": "B", "opts": [["A", "因為作者不喜歡讀書，因此鼓勵兒子賣魚", ""], ["B", "先希望兒子好好讀書，後來才認為學歷不必太高", "文中首先提到：「沒有生來就會賣魚的人。阿公說賣魚要學，學一輩子。爸說賣魚要學，學一下子。他們都說以後不要賣魚，好好讀書。」可知一開始父親並不希望兒子賣魚，而是好好讀書。第四段提到：「在我放棄研究所的那天，我告訴了他，我爸。他只說要賣魚，讀那麼高幹麼？」可見父親態度轉變。"], ["C", "為了幫助家中經濟，自始至終都鼓勵兒子認真讀書", ""], ["D", "先要求兒子賣魚，後發現兒子肯認真向學便不再提賣魚的事", ""]]}, {"n": 6, "q": "林楷倫在文學獎的訪談中提到，自己擅長捕捉販魚職人的生活百態。下列文句何者具有此特徵？", "ans": "D", "opts": [["A", "當時的導師這樣跟我說，埋入了什麼責任又什麼身分的。我的成績還過得去，便沒人管我要不要出席假日輔導", "作者國中時在課業和賣魚生活中掙扎。"], ["B", "我以為我有想過未來，以為我念了較自由的五專，選了醫事技術系，考上證照成為檢驗師，未來便能離開魚攤", "作者上了大學後對於未來的想像，期許離開賣魚生活。"], ["C", "我學會了什麼工作令我厭惡，同時學會了什麼令我嚮往。既然不愛的、討厭的都能做好，那還有什麼不能做呢？我這麼想", "作者接受賣魚生活，從中得到省思與體悟。"], ["D", "嘈雜到嗓門加大，氣味紛雜，聞不出魚臭，……我下了貨車，踏入潮溼，邊走邊點頭或是捶打他人手臂，幾句髒話，都只是招呼", ""]]}, {"n": 7, "q": "〈身為魚販〉：「我以為洗去身上的魚味，穿上怎樣的服裝，又能變成怎樣的人。但作為魚販，是黏著在皮膚上的魚鱗，沒有感覺便嵌在那，覺得癢的時候想拔下那些魚鱗，才發現體膚已經有不一樣的顏色了。」關於這段文字的說明，下列敘述何者正確？", "ans": "D", "opts": [["A", "魚鱗的黏著感表達對魚販工作的熱愛和負責任", "魚鱗的黏著感、嵌在皮膚上，且覺得癢，應是表達對這份工作的無奈、不喜歡，但無法擺脫只能繼續做下去。"], ["B", "不同顏色的體膚象徵作者和同學生活習慣不同", "體膚顏色隨著時間推移，和過去有不同的顏色，主要是表達自己已成為一名魚販。"], ["C", "作者將魚味和服裝串聯說明職業可以任意改變", "作者原以為洗掉魚味、換掉衣服就能改變形象與狀態，但發現沒有辦法。"], ["D", "暗示作者所承受的負擔，讓他不適卻無法擺脫", ""]]}, {"n": 8, "q": "下列關於〈身為魚販〉一文的文句說明，何者正確？", "ans": "C", "opts": [["A", "「我睡了又醒，熟悉的路，醒了又睡，直到過站。」透過作者在公車上睡睡醒醒表現賣魚的辛勞", "藉車站和睡睡醒醒的狀態暗示對當前生活狀態的無奈與迷茫。"], ["B", "「不想多踏一步，踏到殺魚的臺前，拿起魚刨鱗，剪刀剪開魚的皮肉。」傳達出作者雖然身為魚販卻因憐憫魚而不想殺生", "作者是不想當魚販，而非憐憫不想殺生。"], ["C", "「『你要好好讀書，別跟那個哥哥一樣賣魚喔。』站在攤位前，有客人這樣說過。」藉由客人對話傳達出大眾對從事賣魚者的偏見", ""], ["D", "「長襪勒緊了腿。久了，腿上有了一圈的黑線。那一圈腿上的黑線像卡在網縫間脫鱗的魚體。」將償還父親的賭債形象化成黑線，綁住作者的生活", "展現工作的辛苦與不適，同時強調工作環境的艱苦和對身體的影響。"]]}]}, {"kind": "read", "head": "貳 進階實力站　一、閱讀測驗（每題 3 分，共 18 分）(一)", "passage": "　　公孫休<sup>①</sup>相魯而嗜魚，一國盡爭魚而獻之，公孫子不受。其弟諫曰：「夫子嗜魚而不受者何也？」對曰：「夫唯嗜魚，故不受也。夫即受魚，必有下人之色；有下人之色，將枉於法；枉於法則免於相。雖嗜魚，此不必能自給致我魚，我又不能自給魚。即無受魚而不免相，雖嗜魚，我能長自給魚。」此明夫恃<sup>②</sup>人不如自恃也，明於人之為己者，不如己之自為也。<div class='aq-src'>註：①公孫休：即公孫儀。②恃：依靠。</div><div class='aq-src'>（節錄自《韓非子．外儲說右下》）</div><details style='margin-top:10px'><summary>語譯</summary>　　公孫休在魯國當宰相，並且特別喜歡吃魚，國人爭著獻給他魚，他卻不肯接受。他的弟子勸他說：「您喜歡吃魚卻不接受別人的魚，這是為什麼？」他回答說：「我正因為愛吃魚，所以我才不接受。如果我接受了他們獻給我的魚，我就必定要遷就於他們；遷就於他們，就必定會歪曲法律（違法）；歪曲法律則會被免除首相之職。雖然我喜歡吃魚，但這些人不能一直給我魚，我又（因為被免除職位）不能為自己供給魚。如果不收別人給的魚，就不會被免除相位，儘管（我）愛吃魚，但別人不用送我魚，我能夠長期自己供給自己魚。」這是明白了依靠別人不如依靠自己的道理啊，明白了依靠為自己辦事的人，不如自己去辦事。</details>", "items": [{"n": 1, "q": "依據上文，下列何者是公孫休不受魚的原因？<br>(甲)必須看人眼色　(乙)會歪曲法律　(丙)會被免除宰相職務<br>(丁)別人送的魚品質不穩　(戊)擔心魚類資源枯竭", "ans": "B", "opts": [["A", "(甲)(乙)(丁)", ""], ["B", "(甲)(乙)(丙)", "由「必有下人之色；有下人之色，將枉於法；枉於法則免於相」可知。(丁)(戊)本文皆未提及。"], ["C", "(乙)(丙)(丁)", ""], ["D", "(乙)(丁)(戊)", ""]]}, {"n": 2, "q": "依據上文，公孫休的態度，可以用哪個成語形容？", "ans": "D", "opts": [["A", "得天獨厚", "形容人的天賦、社會條件，或是地方的自然環境特別優越。"], ["B", "巧取豪奪", "形容不擇手段的奪取權、財。"], ["C", "錙銖必較", "表示一個人十分小氣，凡事斤斤計較。"], ["D", "兩袖清風", "公孫休面對他人奉獻的魚不肯接受，是因為不願遷就他人，更擔心破壞法律，恐有褻瀆職位的風險，可見為官清廉。(D)比喻官吏清廉，毫無貪贓枉法之事。"]]}, {"n": 3, "q": "文末提到「恃人不如自恃」，何者可以和下列〈身為魚販〉的文字相互呼應？", "ans": "C", "opts": [["A", "賣魚賣雞賣肉不太會成為志願，也非我志向，非我所願", ""], ["B", "我學會了什麼工作令我厭惡，同時學會了什麼令我嚮往", ""], ["C", "裝睡的人叫不醒，爸仍然在賭。為了我的兒女，我得離開", "作者父親不斷賭博，無法期待父親能戒賭，只好自己離開原生家庭。呼應「恃人不如自恃」應該依靠自己的概念。"], ["D", "沒人問過我喜不喜歡賣魚，我卻每日每夜的問自己：不喜歡又能怎樣", ""]]}]}, {"kind": "read", "head": "一、閱讀測驗 (二)", "appraise": "本文書寫作者在一次尋鯨之旅中，遇到六隻虎鯨的經過與感觸，並且在回歸城市後，以人事紛擾和不分黑白，反襯出虎鯨的單純可愛和海洋的純粹美麗。", "passage": "　　牠們（虎鯨）像是應觀眾要求，每番牠們落幕離去，都會因我們的喝采、追隨，而返頭回到舞臺再為我們表演一段。牠們高舉起尾鰭，表演水中倒立；牠們拍打尾鰭，正著拍、仰倒著拍，拍出巨大掌聲樣的盡興水花；也會交錯湧疊，如在表演水中疊羅漢；有一次高速側衝船舷，就在幾乎碰撞尖叫的剎那，又敏捷地側翻，如流星一樣劃一道弧線拋射離去。牠們是一群舞者，在這遼闊的舞臺為我們表演海上芭蕾。也只有海洋這樣的舞臺，才容得下牠們盡情盡興的演出。<br><br>　　有一次，牠們快速離去，船隻用了最大馬力仍然無法追隨，船長著急的喊著：「完了，完了，牠們走了！」就在牠們前方，一大群，至少三、四百隻的弗氏海豚，躍出海面。虎鯨在□□，弗氏海豚惶亂地奔竄逃命。<br><br>　　追獵過後，虎鯨群又回到船邊，像是在和我們戲耍似的高高吐氣。鏡頭溼了、褲腳溼了；霧氣沖噴到我臉上。除了友誼的芬芳，我聞不出牠們剛剛追獵的血腥殘暴。<br><br>　　牠們走了。決定離開的時刻到了，牠們說走說走，如精靈一樣，翻身不見了蹤影。船隻躊躇地轉了幾圈，茫茫海上再也看不到牠們的蹤影。<br><br>　　整整兩個小時的接觸，我感覺到牠們握住了我的心，即使牠們遠遠離去，我也感覺和牠們之間已經絲線牽連，終生不渝。那黑白分明不會褪色的溫潤感覺，如一塊璞玉埋入心底。<br><br>　　此後，每次出海我經常錯覺船舷邊有牠們黑白分明的身影。小組成員有人提議把工作船漆成黑白兩色；我也漸漸喜歡上黑白兩色的衣服——他們印在心底，無法抹滅的清明與黑白。<br><br>　　計畫結束後，回到擾攘的城市，再度面對人事的混濁和黑白模糊的是非。想念海洋，想念那六頭黑白分明的虎鯨。<div class='aq-src'>（節錄自廖鴻基〈黑與白——虎鯨〉）</div>", "items": [{"n": 4, "q": "閱讀本文，思考虎鯨和弗氏海豚的關係，判斷□□應填入下列何種動作最適合？", "ans": "A", "opts": [["A", "獵食", "由「弗氏海豚惶亂地奔竄逃命」及「我聞不出牠們剛剛追獵的血腥殘暴」可以知道虎鯨在捕食弗氏海豚。"], ["B", "嬉鬧", ""], ["C", "悠游", ""], ["D", "分娩", ""]]}, {"n": 5, "q": "依據本文，下列敘述何者正確？", "ans": "D", "opts": [["A", "作者以詳細具體的文字敘述虎鯨和弗氏海豚的互動過程", "(A)(C)作者詳細描寫虎鯨和作者的船隻互動過程，如跳海上芭蕾一樣，和弗氏海豚的互動僅略寫帶過。"], ["B", "虎鯨訓練有素，能理解人類的指令做出海上芭蕾的動作", "這些虎鯨是作者在出海時偶然遇見，作者將虎鯨的動作比擬為舞臺表演，並非指其受過訓練。"], ["C", "虎鯨將作者等人的船隻視為獵物，迅速的追逐作者的船隻", "(A)(C)作者詳細描寫虎鯨和作者的船隻互動過程，如跳海上芭蕾一樣，和弗氏海豚的互動僅略寫帶過。"], ["D", "作者以近距離的觀察與生動的文字，刻劃遇見虎鯨的情景", ""]]}, {"n": 6, "q": "文末提及多次「黑白」兩色，關於此意象的分析，下列敘述何者正確？", "ans": "D", "opts": [["A", "泛指人們從迷思到洞見的認知過程", ""], ["B", "虎鯨的生活特性在白天與黑夜各有不同", ""], ["C", "作者外在的波濤洶湧對照內心的體悟反思", ""], ["D", "以大自然的色彩分明，對比人事的混濁不分", "由文末「回到擾攘的城市，再度面對人事的混濁和黑白模糊的是非」可知。"]]}]}, {"kind": "table", "head": "二、趣味文學體驗（每題 2 分，共 12 分）", "cols": ["", "句子", "答案", "說明"], "rows": [["1", "杜甫寒窗苦讀、奔走考試、拜訪權貴，也都是希望有朝一日能□□□□，報效國家。", "<span class='wk-a'>B</span>", "(B)比喻登上高位。"], ["2", "杜甫的詩歌時常可以反映唐代為政者任意□□□□、調戲婦女的狀況，因此被稱為「詩史」。", "<span class='wk-a'>A</span>", "(A)比喻恣意欺凌百姓，剝取民膏民脂。"], ["3", "杜甫眼見政府為平息戰爭，卻不斷強拉百姓從軍，他認為這樣的方法無異是□□□□，無法真正解決問題。", "<span class='wk-a'>C</span>", "(C)比喻用錯方法，徒勞無功。"], ["4", "受到安史之亂的影響，當時經濟蕭條、安全堪憂，百姓猶如□□□□，生活苦不堪言。", "<span class='wk-a'>D</span>", "(D)比喻身處險境，危在旦夕。"], ["5", "各地擁兵自重，戰爭也不斷□□□□，使得無數百姓成了戰火下無辜的犧牲者，杜甫有感而寫下了無數詩篇。", "<span class='wk-a'>E</span>", "(E)比喻無故受累。"], ["6", "杜甫心想與其坐擁□□□□的女子，享受富貴豪奢的生活，不如實地走訪鄉里，了解民間疾苦。", "<span class='wk-a'>F</span>", "(F)形容女子的容貌美麗。"]], "note": "年年有魚：下列有關「魚」的成語，請填入空格內，使句子讀起來通順。<br>參考選項：(A)魚肉鄉民　(B)魚躍龍門　(C)緣木求魚　(D)魚遊釜中　(E)殃及池魚　(F)沉魚落雁"}, {"kind": "table", "head": "參 挑戰加分站（不計分）", "cols": ["", "文句", "答案", "說明"], "rows": [["1", "到漁場後，將一只水下燈垂入海面，舷邊就熱鬧的游聚了一群（　）。牠們翅翼斜展抖擻，圍住水下燈停止游進，從船上看下去牠們倒像是一群被燈光懾怔住的大型蜻蜓。後斜抖顫的雙翼，使牠們看起來像是在吮吸燈光能量。（改寫自廖鴻基〈飛魚〉）", "<span class='wk-a'>C</span>", "由「翅翼斜展抖擻」、「像是一群……大型蜻蜓」可知。"], ["2", "水裡一隻隻幾乎透明的（　）被槳葉攪出的白沫溢向兩側，形形色色的（　）像極了《星際大戰》中的飛行器在海洋的天空裡翱翔。（出自廖鴻基〈丁挽〉）", "<span class='wk-a'>A</span>", "由「一隻隻幾乎透明的」、「像極了《星際大戰》中的飛行器」可知。"], ["3", "（　）們時常在陽光燦爛海波平靜下成群出現，牠們追隨船隻或在船舷邊跳躍，向漁人現露著頑皮的眼神。（出自廖鴻基〈丁挽〉）", "<span class='wk-a'>B</span>", "由「成群出現」、「跳躍」、「頑皮的眼神」可知。"]], "note": "魚情魚理：文學作品常描寫和敘述海洋生物，請依據圖片的特徵和下列文句描述，替（　）找出正確的海洋生物，並填入答案欄中。<br>參考選項：(A)水母　(B)海豚　(C)飛魚<img src='img/身為魚販/f94112d0393287f3.png' style='max-width:100%;display:block;margin:10px auto;width:640px' alt=''>"}]}, "advQ": [{"kind": "table", "head": "二、進階練習", "cols": ["", "敘述", "符合文意"], "rows": [["1", "翻車魚的更名、徵名活動，是為了要促銷大量捕獲的漁產。", ""], ["2", "因常見翻車魚躺在水面如在作日光浴，而以「翻車」命名。", "<span class='wk-a'>✓</span>"], ["3", "更名活動最後以「曼波」勝出，乃因翻車魚游泳狀似在跳曼波舞。", ""], ["4", "翻車魚活動於水深一百至三百公尺，魚體可達數百、甚至千公斤以上。", "<span class='wk-a'>✓</span>"], ["5", "翻車魚因喜食水母，加上其食用口感如蜇皮般脆口，故又稱為「蜇魚」。", ""], ["6", "地方政府為振興產業，舉辦「翻車魚盛宴」，「更名、徵名」活動本就包括其中。", ""]], "note": "閱讀下文後，判斷下列敘述何者符合文意，在空格處打「✓」：<div class='aq-sub'>　　「翻車」，車子翻倒，是一種交通事故，是不小的意外；引申為——出乎意料的意外。「曼波」，Mambo 音譯，五十多年前源於海地的交際舞，四四拍子，節奏強烈、熱情。<br>　　「翻車」到「曼波」。<br>　　一個憂傷、一個歡樂，南轅北轍的兩件事扯在一起了。<br>　　只是，歡樂的是人，憂傷的是魚。<br>　　翻車魚，正名為翻車魨。活動於水下一百至三百公尺海域，天候好時，牠們會成對成雙浮上水表，躺倒在海面，緩緩搖動背鰭，狀似親密的緊貼著身體，一起躺在海面作日光浴。「翻車」，即形容躺倒海面的模樣，並無憂傷之意。<br>　　翻車魚主食水母，被稱為「蜇魚」；外皮粗糙，肉色雪白、肉質清嫩，饕客美其名為「千貝魚」；其魚腸嚼感清脆，沒什麼滋味，仍被稱以「龍腸」；外形因似魚體斷了後半截，討海人直呼為「魚截」；其卵圓體形，魚體往往數百、甚至可達千公斤以上，小嘴，小眼睛，裙狀尾鰭像曼波舞甩裙，漁人稱牠為「曼波」。<br>　　花蓮海域，翻車魚平均年獲量約兩千條，最高紀錄曾捕獲一萬兩千條。因盛產並富特色，地方政府將漁業、觀光結合，舉辦「翻車魚盛宴」的促銷活動。<br>　　隨著這場盛宴引發的問題，並非活動辦得好不好，也不是該不該以這種方式促銷；帶點諷刺的是，竟是活動單位對「翻車魚」名稱的不安。<br>　　「翻車」，因被參與活動的饕客認為不祥，恐吃了而發生翻車意外；因此，活動單位緊急補辦一場「為翻車魚更名、徵名」活動，是這場「盛宴」中唯一不以吃食為內容的意外插曲。<br>　　經過正名活動，翻車變成曼波。雖然「曼波」是舊瓶新裝，但卻能讓吃者安心，業者高興。一曲曼波，大家起舞。只有翻車魚，這下再也翻不起身了。<div class='aq-src'>（改寫自廖鴻基《腳跡船痕．翻車到曼波》）</div><div class='bk-note'>解析：1 更名、徵名活動是因為饕客認為不祥，怕吃了翻車魚沾名而發生翻車意外。2 由「天候好時，牠們會成對成雙浮上水表……一起躺在海面作日光浴。『翻車』，即形容躺倒海面的模樣」可知。3 文中並未提及「曼波」勝出的原因，僅提及別稱「曼波」的原因。4 由「活動於水下一百至三百公尺海域」、「魚體往往數百、甚至可達千公斤以上」可知。5 稱為「蜇魚」是因為主食水母，與其口感無關。6 原本並無此項活動，為後來臨時加入。</div></div>"}], "basicQ": [{"n": 1, "q": "下列各組「　」內的字，何者讀音相同？", "ans": "D", "opts": [["A", "「勒」緊／「勒」索", "ㄌㄟ／ㄌㄜˋ。"], ["B", "磅「秤」／天「秤」", "ㄔㄥˋ／ㄆㄧㄥˊ。"], ["C", "黏「著」／「著」作", "ㄓㄨㄛˊ／ㄓㄨˋ。"], ["D", "「稱」職／對「稱」", "皆ㄔㄥˋ。"]]}, {"n": 2, "q": "下列文句，何者有錯別字？", "ans": "D", "opts": [["A", "大考前仍在協助家中賣魚，缺席還會讓他覺得愧疚", ""], ["B", "賣魚時沾黏到的魚鱗，貼在皮膚上就像嵌在身體裡", ""], ["C", "經濟不景氣收入減少，以致他必須勒緊褲帶過日子", ""], ["D", "父親的債務束傅著家庭，迫使他放棄升學協助償債", "傅→縛。"]]}, {"n": 3, "q": "下列「　」內的詞語解釋，何者正確？", "ans": "A", "opts": [["A", "踏到殺魚的臺前，拿起魚「刨鱗」，剪刀剪開魚的皮肉：指刮除魚體上的鱗片", ""], ["B", "早上起床穿起雨鞋，橡膠的雨鞋「悶困」了腳，長襪勒緊了腿：指穿著雨鞋讓腳失去知覺", "指悶脹不適。"], ["C", "早上沒有課程，下午滿堂，正職賣魚，讀書像放假，我都這樣「自嘲」：指自責", "以言辭嘲笑自己。"], ["D", "魚販中，有幾個跟我相似的年輕人，有「老派」如阿公的人：指年紀大", "觀念舉止守舊。"]]}, {"n": 4, "q": "關於文中所描述作者的工作與經歷，對①、②的研判應是：<br>①「我站在魚攤，拿起一尾尾冰冷的死魚，秤重刨鱗殺肚，換取更多更多的家庭奉獻。」：作者認為必須不斷重複殺魚販售的工作，才能撐起家庭經濟。<br>②「但作為魚販，是黏著在皮膚上的魚鱗，沒有感覺便嵌在那，覺得癢的時候想拔下那些魚鱗，才發現體膚已經有不一樣的顏色了。」：作者因長時間賣魚，產生皮膚惡化的後遺症。", "ans": "C", "opts": [["A", "①、②皆正確", ""], ["B", "①、②皆錯誤", ""], ["C", "①正確，②錯誤", "②是形容魚販的特質已深入作者體內，並非皮膚惡化的後遺症。"], ["D", "①錯誤，②正確", ""]]}, {"n": 5, "q": "關於本文的寫作手法，何者敘述最適當？", "ans": "D", "opts": [["A", "純粹採用客觀角度敘寫魚市見聞", "文中大量書寫作者主觀的感受與見解。由「既然不愛的、討厭的都能做好，那還有什麼不能做呢？我這麼想」、「身為一名魚販，我很努力，很努力了」可知。"], ["B", "將魚類擬人化，與作者對話，呈現魚販的處境", "並未將魚類擬人化，也未與作者對話。"], ["C", "藉由和客人的交談，呈現一般人對魚販生活的嚮往", "由「『你要好好讀書，別跟那個哥哥一樣賣魚喔。』站在攤位前，有客人這樣說過」，可知一般人對魚販有刻板印象，並未嚮往。"], ["D", "描寫魚市環境，綜合視覺、聽覺、嗅覺、觸覺等感官摹寫", "「嘈雜到嗓門加大」為聽覺摹寫。「氣味紛雜，聞不出魚臭」為嗅覺摹寫。「千百盞燈照出的世界已無黑暗」為視覺摹寫。「踏入潮溼」為觸覺摹寫。"]]}, {"n": 6, "q": "下列有關作者林楷倫的敘述，何者正確？", "ans": "B", "opts": [["A", "為照顧弟妹繼承家業，成為第三代魚販", "作者是為了替父親償債而中斷學業，後來繼承家業成為第三代魚販。"], ["B", "作品描寫魚市見聞，寫實又富戲劇張力", ""], ["C", "僅專注於散文書寫，不曾涉及其他文類", "除散文寫作外，亦出版短篇小說集《雪卡毒》。"], ["D", "未曾獲得文學獎，但寫作能力備受肯定", "曾獲得林榮三文學獎、臺北文學獎及臺中文學獎。"]]}, {"n": 7, "q": "閱讀下列文章後，選出正確的選項：<div class='aq-sub'>　　競標魚貨常常就只是為了面子。<br>　　在冷藏處理場分類好的魚貨，一簍簍被推向拍賣場。<br>　　魚貨的競標是這樣的：現場有處理場、拍賣場、競標處，分別以鐵網分隔，阻止魚販偷換魚或是與貨主串通、私下交易。等待拍賣時，魚販們會靠在鐵網上，看今天有什麼貨，類似在動物園看動物，反過來也很像等待餵食的動物。<br>　　每個漁號都有個按標器，以電腦處理明標，明標的遊戲規則是：每按一下按標器就表示一公斤漲五元或十元。漲到不合理的價格時，會持續競標的人，不是瘋子也不是傻子，他們就像是打了漫長回合的拳擊手，每按一下都是給對方一拳，雙方拳來腳往。<br>　　吵死人的魚市，在出現炒過頭的誇張魚價時，現場只會聽到兩三臺機子按鍵敲打的聲音，先退出的人就在一旁等著看好戲。三國鼎立，退下的那一國，就會說剩下的兩國是白痴。<br>　　這天，兩邊角落都是熟面孔，丸ㄚ跟丸ㄅ。<br>　　兩家商號也不是說一定要這一件魚，那只是場躲不了的對決，是就算自己沒得到，也要盡其所能地填價、讓對方受傷的戰場。每個人都知道那價格太貴，是怎麼賣都賠錢的生意，而有時想弄別人，一不小心就換自己得標。<br>　　關於競標，認真就輸了。<div class='aq-src'>（林楷倫《偽魚販指南．競標》）</div></div>", "ans": "D", "opts": [["A", "為阻止魚販與貨主互通有無，競標都會在密閉的房間內進行", "由「現場有處理場、拍賣場、競標處，分別以鐵網分隔，阻止魚販偷換魚或是與貨主串通、私下交易」可知為非。"], ["B", "競標的過程有時為了贏對方，會拳腳相向，讓自己順利得標", "比喻競標過程像拳擊比賽，並不是真的拳腳相向。"], ["C", "競標方式透過按標器下標，為掌握狀況，按標器由人工處理", "由「每個漁號都有個按標器，以電腦處理明標」可知為非。"], ["D", "競標魚貨有時為了爭面子而哄抬價格，結果自己反成受害者", "由「盡其所能地填價」及「每個人都知道那價格太貴，是怎麼賣都賠錢的生意，而有時想弄別人，一不小心就換自己得標」可知。"]]}, {"n": 8, "q": "臺灣養殖漁業發達，「尚青」的水產總讓許多饕客愛不釋手。以下透過(甲)、(乙)二圖，帶你一覽臺灣養殖漁業概況。閱讀之後，判斷下列何者正確？<img src='img/身為魚販/f110f8a92455dd0b.png' style='max-width:100%;display:block;margin:10px auto;width:620px' alt=''><div class='aq-src'>（資料來源：113 年漁業統計年報）</div>", "ans": "C", "opts": [["A", "甲殼類的蝦與蛤、蜆、牡蠣，皆可透過淡水魚塭或鹹水魚塭養殖", "蛤及牡蠣無法在淡水魚塭養殖。"], ["B", "臺灣養殖漁業型態中，淺海養殖因利用海洋區域養殖，面積最大", "鹹水魚塭養殖面積最大，占 18,768 公頃。"], ["C", "鯛科和石斑透過鹹水魚塭和海面箱網養殖，以鹹水魚塭產量較高", ""], ["D", "虱目魚、吳郭魚及石斑魚，皆是透過淡水魚塭及鹹水魚塭來養殖", "石斑魚並未在淡水魚塭養殖。"]]}],"handoutV2": [{"title": "一、作者與題解", "page": "P.3", "blocks": [["table", "", [["從偽魚販到專職魚販──林楷倫"], ["籍貫", "臺中市 霧峰區人"], ["生平", "中臺科技大學五專部醫事技術系畢業，交通大學 社會與文化研究所肄業，從事魚販工作，並開始嘗試寫小說<br>2016年參加朱宥勳所開設的小說創作課<br>2019年將作品投稿文學獎，並加入「想像朋友寫作會」"], ["創作風格", "認真寫作，描繪魚市所見。他認為各行各業都值得被尊重，魚販的人生也可以很精彩<br>散文風格寫實又富戲劇張力，帶有小說筆法，內容兼具賣魚知識和生命自省，生動敘寫人情事理"], ["成就", "2020年在文學界嶄露頭角，小說雪卡毒獲得林榮三文學獎短篇小說首獎、消失的空間榮獲臺北文學獎小說組評審獎、北疆沒有大紅色的魚獲臺中文學獎小說首獎等<br>2021年，溪底無光獲林榮三文學獎短篇小說三獎"], ["著作", "散文：偽魚販指南、廚房裡的偽魚販<br>小說：雪卡毒"], ["題解要旨", "本文記錄作者投身魚市，最後成為真正魚販的心路歷程<br>原本作者希望透過教育翻轉自己的人生，但父親持續積欠高額賭債，最後只能無奈的放棄學業，成為一名專職魚販<br>在成為魚販的過程中，作者學會從容面對現實，在混亂、疲憊的步調裡，摸索出規則。對世事的領悟從懵懂到透澈，最後坦然接受，提供讀者對生命的省思"]]]]}, {"title": "二、「偽魚販指南」一書", "page": "P.3", "blocks": [["text", "para", "偽，偽裝，指的是作者一開始並非自願當魚販。指南，辨別方向或解決問題的參考資料、途徑，如：旅行指南、處世指南；本課指作者生活的片段。作者擷取魚販日常、真實生活與回憶，寫成這本散文集，是他的第一本書。林楷倫說：「我以為洗去身上的魚味，就能變成不一樣的人。但魚鱗長年緊附，拔扯下來，皮膚已是不同的顏色。」他已變成真正的魚販，並認同這個身分。"]]}, {"title": "(一)文本透視鏡", "page": "P.4", "blocks": [["table", "", [["寫作<br>背景", "林楷倫在出書前曾於臉書撰寫一篇魚市散文，受到讀者鼓勵而萌生出書念頭。他原以為魚販生活平凡無奇，但也正因少有人書寫，更值得記錄。於是他以自身在魚市六年、在市場二十年的經驗為基礎，描繪魚販的日常與真實人生。由於不擅攝影與繪畫，因此他選擇以文字呈現所見人事，將平凡的市場生活化為動人的書寫"]]], ["table", "", [["結構", "段落", "旨意", "讀見真相"], ["起<br>開始投身<br>賣魚工作", "第一段<br>、<br>第二段<br><span class=\"jy-cir\">①</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">國中</span></span>", "作者在週末到家族魚攤協助賣魚，並學習相關知識，家人則希望他好好讀書", "1.作者透過簡單的對話，表達對魚類的認識有限<br>2.在魚攤上經由阿公的教導，展現其學習的心態，同時反映出家庭成員間的互動"], ["起<br>開始投身<br>賣魚工作", "第一段<br>、<br>第二段<br><span class=\"jy-cir\">②</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">國中</span></span>", "作者敘述工作內容及與同學疏離的無奈，自我期許透過讀書來掙脫賣魚的宿命", "1.作者賣魚過程的辛苦，因同學的誤解，產生疏離<br>2.導師的期望、同學對他的羨慕及稱讚，反思自我身分的價值<br>3.努力讀書，期許翻轉魚販第三代的宿命"], ["承<br>賣魚當正職", "第三段<br>五專<br>大學", "應家人要求到魚攤幫忙。父親的賭債讓整個家庭經濟受到綁縛", "1.在學業與工作中掙扎，即使已在學業中找到興趣與未來的希望<br>2.因父親的賭債、阿公的期待，讓他不得不支撐起家庭的重擔，對此充滿無奈"], ["轉<br>專職魚販", "第四段<br>研究所肄業", "作者因家庭因素，放棄高學歷及夢想，成為魚販並接受這個身分", "1.放棄高學歷及夢想，接受社會世俗質疑的眼光，在家庭責任與個人理想間掙扎<br>2.對人生感到迷茫、無奈，也充滿遺憾<br>3.回頭檢視，發覺自己已接受成為魚販的事實"]]], ["table", "", [["合<br><span class=\"jy-cir\">③</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">肯定</span></span><br>魚販的工作", "第五段<br>成家後", "作者敘述成為魚販的心路歷程，完全接受自己已成為一名努力的魚販", "阿公的狀況", "中風在床，幾年後，阿公死去"], ["合<br><span class=\"jy-cir\">④</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">肯定</span></span><br>魚販的工作", "第五段<br>成家後", "作者敘述成為魚販的心路歷程，完全接受自己已成為一名努力的魚販", "自我的成長", "「現在我會吃冷凍的白鯧了，我會輕輕的夾給兒女和自己。我們都吃過現流的白鯧，所以知道冷凍白鯧不好吃」<br>→對於冷凍白鯧的接受，暗示在生活中<span class=\"jy-cir\">⑤</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">接受現實</span></span>的過程，也是對過去種種的回憶與懷念。<br>→<span class=\"jy-cir\">⑥</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">現流的白鯧</span></span>象徵過去的一切；冷凍白鯧則代表<span class=\"jy-cir\">⑦</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">新的生活現實</span></span>"], ["合<br><span class=\"jy-cir\">⑧</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">肯定</span></span><br>魚販的工作", "第五段<br>成家後", "作者敘述成為魚販的心路歷程，完全接受自己已成為一名努力的魚販", "父親的惡習", "「裝睡的人叫不醒，爸仍然在賭」<br>→表達對父親的<span class=\"jy-cir\">⑨</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">失望</span></span><br>→「裝睡的人叫不醒」暗示父親對家庭問題的逃避與無所作為，無論旁人如何努力，他都不改變自己的行為。「爸仍然在賭」指出父親持續沉迷賭博，家庭面臨的困境與壓力"], ["合<br><span class=\"jy-cir\">⑩</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">肯定</span></span><br>魚販的工作", "第五段<br>成家後", "作者敘述成為魚販的心路歷程，完全接受自己已成為一名努力的魚販", "自我的<br><span class=\"jy-cir\">⑪</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">肯定</span></span>", "「身為一名魚販，我很努力，很努力了」<br>→重複「很努力」表示對這個身分的<span class=\"jy-cir\">⑫</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">肯定</span></span>"]]]]}, {"title": "(二)文本異世界", "page": "P.6", "blocks": [["table", "", [["主旨", "作者回憶童年時，祖父是魚販，父母曾經營飲料店，後因父親沉溺賭博，賠掉婚姻與事業，導致他在<span class=\"jy-cir\">①</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">國中</span></span>時期便開始幫忙家中賣魚。本文敘述作者成為魚販的歷程、感受及對生命的理解"], ["敘事視角", "<span class=\"jy-cir\">②</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">第一人稱視角  □第二人稱視角  □第三人稱視角</span></span>"]]], ["table", "", [["寫作特色", "從剖魚到自剖，生命經驗的真實呈現", "這是臺灣第一本真人實事的<span class=\"jy-cir\">③</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">魚販</span></span>寫作，作者凌晨在市場剖魚，學習一堂堂的<span class=\"jy-cir\">④</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">魚販</span></span>學，展開他的魚市人生。讀者可從字裡行間感受到魚市的氣味、魚販與顧客間的人情交流，並對他們投以更多的理解與尊重"], ["寫作特色", "筆法<span class=\"jy-cir\">⑤</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">寫實</span></span>富戲劇張力，兼具幽默與深度", "作者描述魚市見聞，畫面生動，充滿戲劇張力。文字平易卻極具深度，幽默中略帶嘲諷戲謔，又不乏親切感"], ["寫作特色", "面對生命困境、調整步伐重新出發", "作者自小就想盡辦法擺脫宿命，雖卸不掉親情枷鎖，接受自己成為魚販，但正職是魚販的同時，作者將自己的遭遇、心情、對生命的反思，都訴諸文字，一步步實現自我成為作家。這樣的斜槓人生，是作者對命運的解鎖"]]]]}, {"title": "一、形近字", "page": "P.7", "blocks": [["table", "", [["偏旁", "音", "例"], ["烏", "<span class=\"jy-cir\">①</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">ㄨˇ</span></span>", "「摀」住嘴巴"], ["烏", "<span class=\"jy-cir\">②</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">ㄨˋ</span></span>", "山「塢」、船「塢」、村「塢」"], ["欠", "<span class=\"jy-cir\">③</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">ㄑㄧㄢ</span></span>", "鑲「嵌」"], ["欠", "ㄎㄢˇ", "「崁」頂鄉"]]]]}, {"title": "二、一字多音", "page": "P.7", "blocks": [["table", "", [["字", "音", "例"], ["秤", "<span class=\"jy-cir\">①</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">ㄔㄥˋ</span></span>", "「秤」重、磅「秤」"], ["秤", "<span class=\"jy-cir\">②</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">ㄆㄧㄥˊ</span></span>", "天「秤」"], ["刨", "<span class=\"jy-cir\">③</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">ㄆㄠˊ</span></span>", "「刨」鱗、「刨」洞、「刨」坑"], ["刨", "<span class=\"jy-cir\">④</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">ㄅㄠˋ</span></span>", "「刨」冰、「刨」木頭"], ["勒", "<span class=\"jy-cir\">⑤</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">ㄌㄟ</span></span>", "「勒」緊、「勒」死"], ["勒", "<span class=\"jy-cir\">⑥</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">ㄌㄜˋ</span></span>", "懸崖「勒」馬、「勒」令、「勒」索"], ["稱", "<span class=\"jy-cir\">⑦</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">ㄔㄥˋ</span></span>", "「稱」職、「稱」心如意"], ["稱", "<span class=\"jy-cir\">⑧</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">ㄔㄥ</span></span>", "把這包米「稱」一「稱」、「稱」呼、「稱」讚、名「稱」"]]], ["text", "para", "■設問"], ["text", "para", "為了強調語意，以引起讀者的注意，作者有意的設置問題，讓讀者去思索、體會，這種修辭格稱為「設問」。"], ["table", "", [["類別", "定義", "例句"], ["提問", "為提起下文而問，自問自答，答案緊接出現在問句的後面", "問君能有幾多愁？恰似一江春水向東流。　　　　　　 （李煜 虞美人）"], ["懸問", "懸問是內心真的存有疑問，特意提出問句希望得到確切的答案。這是文法學上所謂的「疑問句」", "還要學什麼嗎？<br>你還要讀書嗎？"], ["激問", "又稱「反問」、「反詰」、「詰問」。表面上問而不答，而其答案就在問句本身的反面", "讀那麼高幹麼？<br>不喜歡又能怎樣？<br>那還有什麼不能做呢？"]]]]}, {"title": "一、成語", "page": "P.8", "blocks": [["table", "", [["成語", "釋義", "例句"], ["魚目混珠", "比喻以假亂真。", "這位不肖商人，賣的貨品很多魚目混珠，你要小心免得上當。"], ["魚遊釜中", "比喻身處險境，危在旦夕。", "這位官員貪汙事實確鑿，處境猶如魚遊釜中，自己卻全然不以為意。"], ["如魚得水", "好像魚和水般的契合。比喻得到和自己意氣相投的人或很適合的環境。", "小李時常能提供創新想法，也擅長與人溝通，被指派到行銷部，真是讓他如魚得水，可大展抱負。"], ["緣木求魚", "爬到樹上去找魚。比喻用錯方法，徒勞無功。", "他整天做白日夢，不認真努力，卻只想一步登天，無異是緣木求魚。"], ["臨淵羨魚", "比喻雖有願望，但只憑空妄想，難收實效。", "與其臨淵羨魚，不如退而結網，只有努力去實踐，才有可能成功。"]]]]}, {"title": "二、臺灣常見的食用魚", "page": "P.9", "blocks": [["table", "", [["魚類", "說明", "圖片"], ["午仔魚", "每尾一公斤以上稱做「竹午」，一公斤以下則稱作「大午」，五百克以下稱為「午仔魚」。每年冬至前一個月為其盛產期，價位不高，一般家庭皆能輕鬆購買，為臺灣餐桌上常見的食用魚", ""], ["白鯧", "體為側扁橢圓形，有背鰭一枚，尾鰭深分叉。背部為淡青黑色，腹部色較淡。體長約二十至三十五公分，大的可達六十公分。臺灣主要分布於西部及北部海域", ""], ["土魠魚", "也稱為「馬鮫魚」、「塗魠魚」。體長側扁，背部灰綠色，腹部銀白色，體側約有五十至六十條褐色橫帶。分布極廣，臺灣盛產於西南沿海，尤以臺南、高雄沿海及澎湖近海最多。臺灣知名小吃土魠魚羹，將魚肉塊裹上粉、油炸金黃再放入羹湯中食用", ""], ["虱目魚", "脊椎動物亞門硬骨魚綱。體呈紡錘形，側扁，為臺灣地區淡鹹水養殖魚中的名。魚肉細緻鮮美，為家庭食用魚的佳餚，其加工製品虱目魚丸深受消費者喜愛", ""], ["臺灣鯛", "臺灣鯛是改良後高品質的吳郭魚，體長約十五至二十公分，最大可至三十公分以上，改良優化後最大特色就是少了昔日吳郭魚的「臭土味」", ""]]]]}, {"title": "（一）美味圖景——讀漢代畫像中的魚紋（改寫）\t王仁湘", "page": "P.10", "blocks": [["text", "para", "漢代人對於魚，似乎有著特別的嗜好。長沙 馬王堆出土的漢簡中，就有名列「白羹」的魚羹，主料為肉魚，配有筍、芋、豆、瓠、藕等素菜。又有膾四品，原料為牛、羊、鹿、魚。"], ["text", "para", "魚之為羹、為膾，味道均美。論語云「　　　　　」，其中膾主要指的應是魚膾。禮記 曲禮說「獻孰食者操醬齊」，經學家注解「醬齊為食之主，執主來則食可知，若見芥醬，必知獻魚膾之屬也」，因此有「魚膾芥醬」一語。現代人食生魚片用芥末醬為主要調料，應當是承自周代的傳統。"], ["text", "para", "歷代都有愛魚膾的人，唐代 白居易詩云「秋風一箸鱸魚膾，張翰搖頭喚不回」，吟詠西晉文學家張翰為官時，見秋風一起，便想起了家鄉吳中的菰菜蓴羹鱸魚膾。他頓悟人生一世貴在適意，何苦迢迢千里追求官爵？於是收拾行囊，棄官而歸。另有說法據本草記載，蓴鱸同羹可以下氣止嘔，後人以此推斷張翰在當時意氣抑鬱，隨事嘔逆，故有蓴鱸之思。"], ["text", "para", "蓴為水生草本，葉浮水上，嫩葉可為羹。鱸魚為長江下游近海之魚，肉味鮮美。齊民要術在「羹臛○法」中記有鱸魚蓴羹，其做法是將魚、蓴均下冷水中，另煮豉汁為琥珀色，用調羹味。這是生食之一法，與孔子時以芥醬食膾又有所不同。"], ["text", "para", "（注：○臛：音ㄏㄨㄛˋ，烹煮。）"], ["text", "q", "【　(B)　】1.下列何者最不符合上文所述？"], ["text", "opt", "(A)漢代人嗜好魚羹，主料為魚肉，佐以筍、豆、芋、藕等素菜"], ["text", "opt", "(B)「醬齊為食之主」意指吃飯時要將所有的飲食器具準備齊全"], ["text", "opt", "(C)「蓴羹鱸膾」指張翰頓悟人生貴在適意，具有歸隱故里之思"], ["text", "opt", "(D)「羹臛法」其做法是將魚、蓴均下冷水中，再用豉汁調羹味"], ["text", "exp", "【解析】(B)醬齊，指醬類食品和醬醋拌的小菜。齊，通「韲」，調味用的細碎辛辣食物或菜末。"], ["text", "q", "【　(C)　】2.上文　　　　　內，最適合填入的是："], ["text", "opt", "(A)寧買不值，不買吃食　　　　　(B)飢不可食，寒不可衣"], ["text", "opt", "(C)食不厭精，膾不厭細　　　　　(D)一飲一啄，莫非前定"], ["text", "exp", "【解析】「魚之為羹、為膾，味道均美」意指魚肉要做成羹湯，肉要切得細緻，味道才會美味，故填入(C)，文意妥切適當。(A)寧願把錢花在買貴一點的東西上，也不要把錢用在吃喝上。比喻勸人花錢要花得值得。(B)不可吃、不能穿。比喻不實用。(C)米麥碾舂得愈精白愈好，魚肉切得越細越好。比喻食品精緻，飲食講究。(D)比喻人的生活際遇，都是命中注定的。"], ["text", "q", "【　(A)　】3.依據上文，關於○、○的研判應是："], ["text", "para", "○周代時食生魚片，已知使用芥末醬來做為調料。"], ["text", "para", "○本草記載，蓴鱸同羹有治療意氣抑鬱之效。"], ["text", "opt", "(A)○、○皆正確　　(B)○、○皆錯誤　　(C)○正確，○錯誤　　(D)○錯誤，○正確"], ["text", "exp", "【解析】(A)○由「現代人食生魚片用芥末醬為主要調料，應當是承自周代的傳統」，可知研判正確。○由「據本草記載，蓴鱸同羹可以下氣止嘔，後人以此推斷張翰在當時意氣抑鬱，隨事嘔逆，故有蓴鱸之思」，可知研判正確。"], ["text", "para", "【賞析】本文考據古人嗜魚之風，從論語、禮記、齊民要術等典籍，勾勒出魚膾的歷史脈絡與食藝傳承。亦藉由張翰思鄉辭官，賦予魚膾「適意人生」的象徵意涵，使一味佳餚成為文化與情志的寄託，餘韻悠長。"]]}, {"title": "（二）臺灣漁業資料", "page": "P.11", "blocks": [["table", "", [["臺灣的漁業<br>養殖漁業：利用人為方式養殖水生動、植物，可分為陸上養殖及淺海養殖兩大類。<br>沿近海漁業：在我國專屬經濟海域（離岸200海浬內）從事漁撈作業者。<br>遠洋漁業：指於公海或他國領海或專屬經濟海域，從事漁撈作業。<br>112年漁戶數、漁戶人口數及漁業從業人數<br>漁業法<br>第 2 條：本法所稱主管機關：在中央為行政院 農業委員會；在直轄市為直轄市政府；在縣（市）為縣（市）政府。<br>第 3 條：本法所稱漁業，係指採捕或養殖水產動植物業，及其附屬之加工、運銷業。<br>第 4 條：1.本法所稱漁業人，係指漁業權人、入漁權人或其他依本法經營漁業之人。<br>　　　　 2.本法所稱漁業從業人，係指漁船船員及其他為漁業人採捕或養殖水產動植物之人。<br>第 5 條：漁業人以中華民國人為限。但外國人經中央主管機關核准與中華民國漁業人合作經營漁業者，不在此限。"]]], ["text", "q", "【　(B)　】1.依據上述資料，下列何者最符合「漁戶數」所述？"], ["text", "opt", "(A)112年底漁戶數將超過13萬戶　　　　(B)遠洋漁戶數比近海少13,303戶"], ["text", "opt", "(C)「以內陸漁撈為主者」的占比最多　　 (D)我國海面養殖業比內陸養殖興盛"], ["text", "exp", "【解析】(A)112年底漁戶數129,136戶，未超過13萬戶。(B)近海18,469－遠洋5,166＝13,303戶。(C)「以內陸漁撈為主者」4,088戶，為漁戶數中占比最少。(D)「以海面養殖為主者」為8,186戶，「以內陸養殖為主者」為27,413戶，可知內陸養殖比海面養殖興盛。"], ["text", "q", "【　(B)　】2.阿明在市場的鮮魚攤上看到販售的魚類如下。參考上述資料，判斷圖中何者屬於「遠洋魚類」？"], ["text", "opt", "(A)(甲)(丙)(丁)"], ["text", "opt", "(B)(乙)(丙)(丁)"], ["text", "opt", "(C)(甲)(乙)(丙)(丁)"], ["text", "opt", "(D)(乙)(丙)(丁)(戊)"], ["text", "exp", "【解析】(甲)養殖魚類。草魚，生活於淡水中，因食水草而得名。也稱為「鯇（ㄏㄨㄢˋ）魚」，是臺灣地區重要的養殖魚類。(乙)遠洋魚類。秋刀魚，生存水域在太平洋北部，因盛產於秋天，顏色銀白且身形修長，就像一把短刀，故名為「秋刀魚」。(丙)遠洋魚類。旗魚，太平洋、印度洋、大西洋均有分布。種類繁多，包括劍旗魚、立翅旗魚、黑皮旗魚、紅肉旗魚等。(丁)遠洋魚類。魷魚，大多產於阿根廷、美洲、西北太平洋等地區。(戊)沿近海魚類。烏魚，每年冬季洄游至臺灣南部西岸產卵。故答案選(B)。"], ["text", "q", "【　(A)　】3.依據上文，下列敘述何者最符合文意？"], ["text", "opt", "(A)112年底漁戶人口數達到32萬人以上，從事項目包含漁業之運銷業"], ["text", "opt", "(B)漁業人係指漁船船員及其他為漁業人採捕或從事養殖水產動植物之人"], ["text", "opt", "(C)漁戶人口數統計包含中華民國、外國人及與我國漁業人合作經營業者"], ["text", "opt", "(D)《漁業法》最高主管機關為行政院 農業委員會，縣（市）政府沒有管理權"], ["text", "exp", "【解析】(A)由「本法所稱漁業，係指採捕或養殖水產動植物業，及其附屬之加工、運銷業」可知。(B)漁業人，係指漁業權人、入漁權人或其他依本法經營漁業之人。(C)漁戶人口數，以中華民國人為限。(D)由「本法所稱主管機關：在中央為行政院 農業委員會；在直轄市為直轄市政府；在縣（市）為縣（市）政府」，可知縣（市）政府具有管理權。"], ["text", "para", "【　 　】1.若要使下文的理路連貫有序，○、○、○、○、○最適當的排列應是：\t【111統測】"], ["text", "para", "魚塭與魚塘雖大約在相同時期引進臺灣，但魚塘因魚苗取得不易，"], ["text", "para", "○因此大多僅是農家副業，"], ["text", "para", "○以及須克服水源補充問題，"], ["text", "para", "○反觀魚塭雖侷限在臺灣西南沿海，"], ["text", "para", "○卻是適合環境條件的土地利用方式，"], ["text", "para", "○故養殖活動得依附水稻農業生態體系，"], ["text", "para", "遂發展為重要的養殖型態。"], ["text", "opt", "(A)○○○○○"], ["text", "opt", "(B)○○○○○"], ["text", "opt", "(C)○○○○○"], ["text", "opt", "(D)○○○○○"], ["text", "sub", "2.閱讀下文，回答第(1)、(2)題：\t【106統測】"], ["text", "para", "【　 　】(1)依據上圖，下列敘述何者正確？"], ["text", "opt", "(A)鯊魚體內環境毒素多，唯魚鰭毒稀而可食"], ["text", "opt", "(B)鯊魚長壽且繁殖力強，但敵不過人類濫捕"], ["text", "opt", "(C)鯊魚割鰭後行動遲緩，故攻擊力不及鱷魚"], ["text", "opt", "(D)鯊魚的物體辨識力差，並非專嗜人類獵食"], ["text", "para", "【　 　】(2)上圖倡導「不食魚翅，拒絕買賣」以挽救鯊魚，主要是基於何種理由？"], ["text", "opt", "(A)數罟不入洿池，魚鱉不可勝食也"], ["text", "opt", "(B)夫膻臭之欲不止，殺害之機不已"], ["text", "opt", "(C)竭誠則胡 越為一體，傲物則骨肉為行路"], ["text", "opt", "(D)求福莫過齋戒佈施，求壽莫過不殺放生"], ["text", "para", "1.【答案】(B)"], ["text", "exp", "【解析】(B)從文章開頭可知主體為「魚塭」與「魚塘」兩個對象，再由「但魚塘因魚苗取得不易」的轉折語氣可知「魚塘」必須克服某種因素或問題，必須依賴某種條件才得以存在，因此○○相連；而「魚塘」在這種情況下，因此造成某種結果，故文意接續○。又從「魚塘」的發展，對照「魚塭」，文意脈絡接續○；最後由末句「遂發展為重要的養殖型態」，可知是描述「魚塭」恰巧適合這樣的環境條件，因此接○。文章改寫自洪新恩 從虱目魚看臺灣。"], ["text", "para", "2.(1)【答案】(D)"], ["text", "exp", "【解析】(A)鯊魚鰭「汞含量高，並驗出誘發阿茲海默症的神經毒素」，因此「唯魚鰭毒稀而可食」為非。(B)鯊魚「產子數少」明顯與「繁殖力強」相違。(C)敘述鯊魚的「攻擊力不及鱷魚」，圖中亦未提及。(D)呼應圖中鯊魚無法分辨海豹、海龜、人，物體辨識能力確實很差。因此正確答案為(D)。"], ["text", "para", "(2)【答案】(B)"], ["text", "exp", "【解析】題幹倡導「不食魚翅，拒絕買賣」是基於保護鯊魚生態，並期許人類對鯊魚能有更多的正確認識，與(A)「不可勝食」無關，也跟(C)強調的竭誠、傲慢沾不上邊，更不是(D)所言為了「求福求壽」，而是和人類的欲望連動，因此正確答案為(B)。"], ["text", "trans", "【語譯】(A)不使用細密的漁網在池塘內捕魚，魚鱉就吃不完了。（數，音ㄘㄨˋ，細密。罟，音ㄍㄨˇ，網的總稱。洿池，池塘。洿，音ㄨ。）孟子 梁惠王上。(B)只要臊臭的欲望不停止，殺害的動機也就不會終止。（膻，音ㄕㄢ，同「羶」，羊身上的臊味。）譚峭 化書卷四 仁化 畋漁。(C)竭誠待人，即使關係疏遠的人也能同甘共苦，傲氣凌人，那麼至親的親人也會形同路人。魏徵 諫太宗十思疏。(D)要追求福祉最好的就是齋戒佈施，要求取長壽莫過於不殺生、多放生。大乘金剛經第十三。"]]}],"aHand": {"title": "第一部分：非選擇題（共 22 分）", "secs": [{"h": "一、字音字形（每題 2 分，共 12 分）", "items": [["1", "「懵」懂", "ㄇㄥˊ"], ["2", "「勒」緊", "ㄌㄟ"], ["3", "「摀」住嘴", "ㄨˇ"], ["4", "空「ㄉㄤˋ」無人", "蕩"], ["5", "解「ㄆㄡˇ」學", "剖"], ["6", "熱「ㄌㄨㄛˋ」", "絡"]]}, {"h": "二、解釋（每題 2 分，共 10 分）", "items": [["1", "嘴刁", "指吃東西挑剔，過分講究。"], ["2", "虛耗", "浪費、耗損。"], ["3", "自嘲", "以言辭嘲笑自己。"], ["4", "頹敗", "衰落、敗壞。"], ["5", "老派", "觀念舉止守舊。"]]}]},"aQuiz": [{"n": 1, "ans": "B", "stem": "下列文句，何者用字完全正確", "opts": [["A", "為了成為秤職的銷售員，他努力的參加研習與考取證照"], ["B", "住在菜市場旁邊，常常聽到小販們嘈雜的叫賣聲"], ["C", "悶熱的午後忽然一陣涼風習來，使我通體舒暢"], ["D", "這場戲劇帶有對時事的嘲諷戲虐，令人印象深刻"]], "exp": "(A)「稱」職。(C)涼風「襲」來。(D)嘲諷戲「謔」。", "trans": "", "per": {"A": "「稱」職。", "C": "涼風「襲」來。", "D": "嘲諷戲「謔」。"}, "psg": "", "need_img": false}, {"n": 2, "ans": "C", "stem": "下列各組「 」內的字，何者意義相同", "opts": [["A", "「稱」心如意／「稱」兄道弟"], ["B", "「頹」敗衰落╱心情「頹」喪"], ["C", "遮風「蔽」雨╱衣不「蔽」體"], ["D", "壓力束「縛」╱手無「縛」雞之力"]], "exp": "(A)適合╱叫、叫做。 (B)衰敗、敗壞╱委靡不振的樣子。 (C)遮蓋、擋住。 (D)拘束、約束╱用繩捆綁。", "trans": "", "per": {"A": "適合╱叫、叫做。", "B": "衰敗、敗壞╱委靡不振的樣子。", "C": "遮蓋、擋住。", "D": "拘束、約束╱用繩捆綁。"}, "psg": "", "need_img": false}, {"n": 3, "ans": "C", "stem": "閱讀下文，判斷畫底線處的文句，何者有明顯的語病？", "opts": [["A", "(甲)"], ["B", "(乙)"], ["C", "(丙)"], ["D", "(丁)"]], "exp": "(丙)想不開時，走一段海灘是為了要「紓解」心中的不平之氣，而非「凝聚」。", "trans": "", "per": {"C": "想不開時，走一段海灘是為了要「紓解」心中的不平之氣，而非「凝聚」。"}, "psg": "在清晨的灘上，我常遇見(甲)<u>漁筏從海上帶回來形形色色的魚蝦</u>。(乙)<u>年輕的心常有怨尤，不滿這、不滿那</u>。(丙)<u>想不開時，就走一段海灘讓浪濤聲凝聚心中的塊壘</u>；(丁)<u>不想參加升學考試時，便憧憬當個離岸遠去的船員</u>；生命遇挫折時，便一步步走向海邊，聆聽濤聲的安慰。<div class='aq-src'>（廖鴻基〈我喜歡的海〉）</div>", "need_img": false}, {"n": 4, "ans": "D", "stem": "閱讀下文，推斷□□□□內最適合填入的詞語依序為何？", "opts": [["A", "得魚忘筌／狼吞虎嚥／齒頰留香"], ["B", "情有獨鍾／偶一為之／一往情深"], ["C", "偶一為之／千篇一律／無所事事"], ["D", "一往情深／大快朵頤／齒頰留香"]], "exp": "由「幾乎無日不吃魚」可推斷對吃魚情感深厚，因此填「一往情深」（指人情感深厚、真摯，一旦投入，始終不改）較為適當╱由「每天在市場口的攤販……吃虱目魚粥」可知在吃的當下是「大快朵頤」（指飽食愉快的樣子）較為適當╱最後由「撫著腫脹的肚子」，而且「心滿意足的離開」，可呼應「齒頰留香」（形容食物味道鮮美，令人回味無窮），味道鮮美因此回味無窮，故選(D)。(A)得魚忘筌：比喻人在成功後就忘本背恩╱狼吞虎嚥：形容吃東西又急又猛，大口吞食的樣子。(B)情有獨鍾：特別鍾愛某一事物╱偶一為之：偶然做一次。(C)千篇一律：形式或內容毫無變化╱無所事事：閒蕩無事的樣子。", "trans": "", "per": {"D": "由「幾乎無日不吃魚」可推斷對吃魚情感深厚，因此填「一往情深」（指人情感深厚、真摯，一旦投入，始終不改）較為適當╱由「每天在市場口的攤販……吃虱目魚粥」可知在吃的當下是「大快朵頤」（指飽食愉快的樣子）較為適當╱最後由「撫著腫脹的肚子」，而且「心滿意足的離開」，可呼應「齒頰留香」（形容食物味道鮮美，令人回味無窮），味道鮮美因此回味無窮，故選(D)。", "A": "得魚忘筌：比喻人在成功後就忘本背恩╱狼吞虎嚥：形容吃東西又急又猛，大口吞食的樣子。", "B": "情有獨鍾：特別鍾愛某一事物╱偶一為之：偶然做一次。", "C": "千篇一律：形式或內容毫無變化╱無所事事：閒蕩無事的樣子。"}, "psg": "我對魚可謂□□□□，寬鬆地講，幾乎無日不吃魚。青春期，我的早餐常是一條肥碩的虱目魚和一大碗麵線，每天在市場口的攤販□□□□的吃虱目魚粥，已經是我長年的食魚習慣。如今每隔一段時日，我總會刻意到南機場公寓的路邊攤，坐下來痛快地吃虱目魚粥，直到撫著腫脹的肚子，才□□□□，心滿意足的離開。<div class='aq-src'>（改寫自焦桐〈論吃魚〉）</div>", "need_img": false}, {"n": 5, "ans": "D", "stem": "若要使下文的理路連貫有序，①、②、③、④、⑤最適當的排列應是：", "opts": [["A", "②③④⑤①"], ["B", "③①④⑤②"], ["C", "①④③②⑤"], ["D", "②④①⑤③"]], "exp": "由「窄小的門面」可推知下一句以描述「門的主體或行為」，因此下句接②先拉開細格子的木門，就會看到垂掛在門片上的布幔（門簾），故接④。然後比較與附近民宿的分別，接①，最後在店前「無論……，總是……」，可知先⑤再③，正確答案為(D)。", "trans": "", "per": {"D": "由「窄小的門面」可推知下一句以描述「門的主體或行為」，因此下句接②先拉開細格子的木門，就會看到垂掛在門片上的布幔（門簾），故接④。然後比較與附近民宿的分別，接①，最後在店前「無論……，總是……」，可知先⑤再③，正確答案為(D)。"}, "psg": "那個料理亭可能與附近的民家沒有什麼分別，木造的日式房屋，窄小的門面，　①所不同者，②拉開細格子的木門，③他們的店前總是掃除潔淨，④可能還垂著一幅藍色蠟染的布幔，⑤無論你什麼時候進去，　在那石板地面上潑灑著水的。<div class='aq-src'>（林文月《飲膳札記》）</div>", "need_img": false}, {"n": 6, "ans": "C", "stem": "「阿公說賣魚要學，學一輩子。爸說賣魚要學，學一下子。」透過「一輩子」和「一下子」對比，展現對賣魚不同的觀點。下列文句何者運用相同對比手法", "opts": [["A", "湖邊山上，青一塊，紫一塊，綠一塊"], ["B", "義大利的麵包倒不黑，可是硬得像鞋底"], ["C", "創業的人都會自然而然的想到上天；而敗家的人卻無時不想到自己"], ["D", "日頭是追不到的，我沒有夸父的荒誕，但晚景的溫存卻被我這樣偷嘗了不少"]], "exp": "題幹與 (C)映襯。(A)類疊。吳敬梓〈王冕的少年時代〉。(B)譬喻、誇飾。鍾理和〈生活與生存〉。(C)以「創業的人」與「敗家的人」對立比照，前者「想到上天」與後者「想到自己」形成對比，也藉差異凸顯不同人生態度。陳之藩〈謝天〉。(D)轉化（形象化）徐志摩〈我所知道的康橋〉。", "trans": "", "per": {"C": "以「創業的人」與「敗家的人」對立比照，前者「想到上天」與後者「想到自己」形成對比，也藉差異凸顯不同人生態度。陳之藩〈謝天〉。", "A": "類疊。吳敬梓〈王冕的少年時代〉。", "B": "譬喻、誇飾。鍾理和〈生活與生存〉。", "D": "轉化（形象化）徐志摩〈我所知道的康橋〉。"}, "psg": "", "need_img": false}, {"n": 7, "ans": "D", "stem": "下列文句，何者以反問語氣表達無奈之意", "opts": [["A", "「還要學什麼嗎？」我問阿公"], ["B", "既然不愛的、討厭的都能做好，那還有什麼不能做呢"], ["C", "我會將手掌摀住同學的嘴，說：「很臭嗎？」"], ["D", "沒人問過我喜不喜歡賣魚，我卻每日每夜的問自己：不喜歡又能怎樣"]], "exp": "(A)(C)懸問。(B)激問。顯示作者在面對生活挑戰時充滿勇氣與決心。", "trans": "", "per": {"A": "懸問。", "C": "懸問。", "B": "激問。顯示作者在面對生活挑戰時充滿勇氣與決心。"}, "psg": "", "need_img": false}, {"n": 8, "ans": "C", "stem": "「沒有出生就會賣魚的人。沒有什麼東西，不用學一輩子。身為一名魚販，我很努力，很努力了。」上文中作者的心境與下列何者最接近", "opts": [["A", "老僧已死成新塔，壞壁無由見舊題"], ["B", "半畝方塘一鑑開，天光雲影共徘徊"], ["C", "長風破浪會有時，直掛雲帆濟滄海"], ["D", "白日放歌須縱酒，青春作伴好還鄉"]], "exp": "作者重複「很努力」是對自己魚販身分的肯定，表達儘管非出於志願承擔魚販工作，仍努力把事情做好的心境。這種「面對挑戰的勇氣與決心」，與 (C)所展現的逆風而行、破浪前進的心境最為相近。(A)描述今非昔比的慨嘆。(B)描述讀書時思路明暢的體會。(D)描述欣喜返鄉的心情。", "trans": "(A)奉閒和尚剛過世不久，他的骨灰儲藏在新建的佛塔中，昔日僧房的牆壁已毀壞，無法看到舊時壁上的題詩。蘇軾〈和子由澠池懷舊〉。 (B)這半畝大的方塘，好像一面展開的明鏡，天光和雲影倒映在方形的水塘中，一起緩緩的移動。朱熹〈觀書有感〉之一。 (C)總會有一天，我能乘長風、破巨浪，掛起高高的雲帆，在大海中勇往直前！李白〈行路難〉。 (D)白天時我引吭高歌，並且縱情飲酒，在春光裡，正好與我作伴返回故鄉。杜甫〈聞官軍收河南河北〉。", "per": {"C": "作者重複「很努力」是對自己魚販身分的肯定，表達儘管非出於志願承擔魚販工作，仍努力把事情做好的心境。這種「面對挑戰的勇氣與決心」，與(C)所展現的逆風而行、破浪前進的心境最為相近。", "A": "描述今非昔比的慨嘆。", "B": "描述讀書時思路明暢的體會。", "D": "描述欣喜返鄉的心情。"}, "psg": "", "need_img": false}, {"n": 9, "ans": "B", "stem": "「現在我會吃冷凍的白鯧了，我會輕輕的夾給兒女和自己。我們都吃過現流的白鯧，所以知道冷凍白鯧不好吃。」此段文句作者所欲表達的觀點，與下列何者最接近", "opts": [["A", "感嘆自己年老一事無成，被迫接受現實生活的殘酷"], ["B", "表達自己願意與現實生活妥協的心情，以及對過去種種的回憶與懷念"], ["C", "惋惜現在已經沒有現流白鯧，只能勉強自己接受冷凍白鯧的無奈"], ["D", "說明自己與家人同甘共苦，即使是不好吃的東西也要一同承擔"]], "exp": "(B)作者表達以前吃過好吃的現流白鯧，如今冷凍白鯧即使不好吃，他與家人仍然甘之如飴，說明與現實生活妥協的心情。", "trans": "", "per": {"B": "作者表達以前吃過好吃的現流白鯧，如今冷凍白鯧即使不好吃，他與家人仍然甘之如飴，說明與現實生活妥協的心情。"}, "psg": "", "need_img": false}, {"n": 10, "ans": "D", "stem": "關於下文運用「場景呈現處境與心情」的寫作手法，何者敘述最適當？", "opts": [["A", "以「乘車方向」暗示，自己要堅定走一條與眾不同的道路"], ["B", "以「無人和排滿同學」的差異，批判眾人對城市生活嚮往"], ["C", "以「不同群坐上不同班車」，強化自己所歸屬群體微小脆弱"], ["D", "以「坐在最後一排的中間座位」，強調自己與他人的疏離感"]], "exp": "「無人等車」與「排滿同學」對比，凸顯自己與他人的不同，而「沒有一個人向我招手」則加強了孤獨感。最後「我坐在最後一排五人的座位，中間只有我一人」，以空蕩的位置象徵自身的孤立，強調與他人的疏離感，最符合選項(D)。", "trans": "", "per": {"D": "「無人等車」與「排滿同學」對比，凸顯自己與他人的不同，而「沒有一個人向我招手」則加強了孤獨感。最後「我坐在最後一排五人的座位，中間只有我一人」，以空蕩的位置象徵自身的孤立，強調與他人的疏離感，最符合選項(D)。"}, "psg": "往我家方向的站牌，無人等車；對面往城市的站牌，排滿了同學，沒有一個人向我招手。他們坐上一班車，另一群再坐上另一班，直到我等的公車來到。我坐在最後一排五人的座位，中間只有我一人。<div class='aq-src'>（林楷倫〈身為魚販〉）</div>", "need_img": false}, {"n": 11, "ans": "C", "stem": "「我以為我有想過未來，以為我念了較自由的五專，選了醫事技術系，考上證照成為檢驗師，未來便能離開魚攤。」作者的心境與下列文句何者最相似", "opts": [["A", "我滿懷信心地踏上新生活，迎接新階段的未知挑戰，充滿期待與憧憬"], ["B", "一開始我認為這條路不值得，但愈走愈發現，這條路因艱困而有意義"], ["C", "我本想著走出家鄉，便能擺脫過去一切，未曾想過記憶糾纏不曾遠離"], ["D", "童年時的夢想隨著年齡增長而改變，回首過往、莞爾一笑，全是感激"]], "exp": "題幹中「以為」兩次重複，顯示出對未來的規劃與現實之間的落差，隱含一種誤以為能擺脫過去，卻仍受其影響的無奈與無力感。 (C)描述了試圖擺脫過去卻發現記憶無法抹去的感受，與題幹情境最為相似。", "trans": "", "per": {"C": "描述了試圖擺脫過去卻發現記憶無法抹去的感受，與題幹情境最為相似。"}, "psg": "", "need_img": false}, {"n": 12, "ans": "B", "stem": "「早上起床穿起雨鞋，橡膠的雨鞋悶困了腳，長襪勒緊了腿。久了，腿上有了一圈的黑線。那一圈腿上的黑線像卡在網縫間脫鱗的魚體。」關於上文中的「黑線」，何者最符合其象徵意涵", "opts": [["A", "象徵時間流逝所留下的痕跡是成長的必經過程"], ["B", "象徵身體被工作束縛的不適，暗示內心的壓抑無奈"], ["C", "象徵勞動者的光榮印記，顯示對工作環境認同適應"], ["D", "象徵身為魚販傳承印記，暗示接納重大的家族使命"]], "exp": "(B)文中的「黑線」是因雨鞋與長襪的束縛而產生的痕跡，被比喻為「卡在網縫間脫鱗的魚體」，顯示出一種被限制、無法掙脫的狀態，與作者內心的壓抑和無奈相呼應。", "trans": "", "per": {"B": "文中的「黑線」是因雨鞋與長襪的束縛而產生的痕跡，被比喻為「卡在網縫間脫鱗的魚體」，顯示出一種被限制、無法掙脫的狀態，與作者內心的壓抑和無奈相呼應。"}, "psg": "", "need_img": false}, {"n": 13, "ans": "B", "stem": "林楷倫〈身為魚販〉談論了自己青少年時期，做為魚販之子對交友產生的影響。若依課文內容，繪製常用於「分析原因」的「魚骨圖」，｛　｝、〔　〕最適合填入何者？", "opts": [["A", "①時間運用／①－1 不上假日輔導，同學嫉妒討厭／②身體狀況／②－1 勞動晒日時長，皮膚黝黑難看"], ["B", "①時間運用／①－1 假日仍要工作，難有時間交友／②身體狀況／②－1 身上有魚腥味，影響同學感受"], ["C", "①性格養成／①－1 工作導致少言，與同儕難深交／②日常表現／②－1 勞動沒空讀書，成績不佳惹嫌"], ["D", "①性格養成／①－1 工作說垃圾話，爽朗容易親近／②日常表現／②－1 處事態度極佳，同學尊敬重視"]], "exp": "(B)依據課文，時間的限制上，作者因假日仍要工作，無法上假日輔導及和同學出遊，難以與同學深交；身上因魚販工作帶來魚腥臭味，影響同學感受。", "trans": "", "per": {"B": "依據課文，時間的限制上，作者因假日仍要工作，無法上假日輔導及和同學出遊，難以與同學深交；身上因魚販工作帶來魚腥臭味，影響同學感受。"}, "psg": "", "need_img": false, "imgs": [["", "img/身為魚販/2746b55d8447540d.png"]]}, {"n": 14, "ans": "C", "stem": "文學中透過對話的呈現，可看見許多值得玩味的「言外之意」。關於〈身為魚販〉中，「對話展現的言外之意」，何者說明最適當？<br>「你要好好讀書，別跟那個哥哥一樣賣魚喔。」<br>「對啊，要好好讀書喔，別像我一樣讀交大喔。」", "opts": [["A", "讀書若只讀到交大，容易被他人瞧不起"], ["B", "當今社會競爭激烈，連賣魚都讀到交大"], ["C", "對於職業與勞動型態，仍有人存在偏見"], ["D", "賣魚的人學歷需求不高，讀書幫助不大"]], "exp": "(C)客人的言論透露出對「賣魚」這類勞動工作的偏見，認為讀書的目的應是脫離此類職業，而作者的反諷則反擊這種刻板印象。", "trans": "", "per": {"C": "客人的言論透露出對「賣魚」這類勞動工作的偏見，認為讀書的目的應是脫離此類職業，而作者的反諷則反擊這種刻板印象。"}, "psg": "", "need_img": false}, {"n": 15, "ans": "A", "stem": "林楷倫在〈身為魚販〉中，有意識的依時間軸娓娓說故事。若依據該文章，檢視不同階段對「成為魚販」的想法和行動，下表何者正確？<br><span style='font-weight:400'>（表格欄位依序：階段／自己的想法／阿公或父親的角色／成為魚販的學習內容）</span>", "opts": [["A", "國中／不想成為魚販／都要作者好好讀書／辨識魚類與新鮮度"], ["B", "五專／開始不想讀書／阿公賭債影響作者／秤重、刨鱗、殺肚"], ["C", "大學／大學畢業為優先／阿公要作者好好讀書／開船捕魚"], ["D", "研究所／認分成為魚販／父親憤怒作者放棄學業／開始批貨"]], "exp": "(B)五專階段，作者仍想讀書改變人生；阿公並未涉賭，而是父親。(C)大學階段，作者「正職賣魚，讀書像放假」，阿公與父親要作者幫家裡賣魚，但未學習開船捕魚。(D)研究所時，作者決定專職賣魚，父親並沒憤怒，反而認為「要賣魚，讀那麼高幹麼？」", "trans": "", "per": {"B": "五專階段，作者仍想讀書改變人生；阿公並未涉賭，而是父親。", "C": "大學階段，作者「正職賣魚，讀書像放假」，阿公與父親要作者幫家裡賣魚，但未學習開船捕魚。", "D": "研究所時，作者決定專職賣魚，父親並沒憤怒，反而認為「要賣魚，讀那麼高幹麼？」"}, "psg": "", "need_img": false}, {"n": 16, "ans": "B", "stem": "〈身為魚販〉一文描寫作者成長過程中與魚販生活的互動及家族故事，下列敘述，何者最能反映出文章的重點內容", "opts": [["A", "作者以沉重嚴肅的口吻抒發身為魚販之子的自卑，以及與同學之間的疏離"], ["B", "本文採用第一人稱的角度，描述自己從排斥當魚販，到坦然接受成為專職魚販的心路歷程"], ["C", "作者透過與爸爸對話的方式，學會分辨三種不同鯧魚特徵的知識"], ["D", "作者以層遞的手法，詳寫家中的賣魚事業，從阿公、爸爸到自己一路走來的心路歷程"]], "exp": "(A)以輕鬆詼諧的口吻敘述。(C)與阿公的對話。(D)以順敘的筆法，描述家中賣魚事業的心路歷程。", "trans": "", "per": {"A": "以輕鬆詼諧的口吻敘述。", "C": "與阿公的對話。", "D": "以順敘的筆法，描述家中賣魚事業的心路歷程。"}, "psg": "", "need_img": false}, {"n": 17, "ans": "C", "stem": "臺灣羽球名將戴資穎在東京奧運會失利後曾有感而發：「好與壞都是成長過程，最重要的就是要相信自己。」說明成長過程不會一帆風順，一定有甜美的果實也會有陣痛與低潮，最重要的就是要有成長的勇氣與決心。此觀點與下列何者最接近", "opts": [["A", "「讀那麼高，幹麼賣魚啦？」又有人問我。我更難回答了。「只是工作。」我說"], ["B", "他不知道，我就算好好讀書，還是得賣魚。在我放棄研究所的那天，我告訴了他，我爸"], ["C", "我學會了什麼工作令我厭惡，同時學會了什麼令我嚮往。既然不愛的、討厭的都能做好，那還有什麼不能做呢"], ["D", "現在我會吃冷凍的白鯧了，我會輕輕的夾給兒女和自己。我們都吃過現流的白鯧，所以知道冷凍白鯧不好吃"]], "exp": "由「既然不愛的、討厭的都能做好，那還有什麼不能做呢」，顯見面對挑戰的勇氣與決心，故選(C)。(A)(B)(D)皆描述作者面對生活壓力和家庭責任，最終只能與現實妥協。", "trans": "", "per": {"A": "皆描述作者面對生活壓力和家庭責任，最終只能與現實妥協。", "B": "皆描述作者面對生活壓力和家庭責任，最終只能與現實妥協。", "D": "皆描述作者面對生活壓力和家庭責任，最終只能與現實妥協。", "C": "由「既然不愛的、討厭的都能做好，那還有什麼不能做呢」，顯見面對挑戰的勇氣與決心，故選(C)。"}, "psg": "", "need_img": false}, {"n": 18, "ans": "C", "stem": "翰林市場管委會特別以題辭表揚年度業績前四名的攤商，下列何者最適當？", "opts": [["A", "恭喜　王記肉品：妙手回春藝超群"], ["B", "恭喜　蔡記水果：庖丁解牛神乎技"], ["C", "恭喜　林氏生魚片：齒頰留香味俱全"], ["D", "恭喜　許氏飲品：為民喉舌不間斷"]], "exp": "(A)「妙手回春」為醫界祝賀詞。(B)「庖丁解牛」比喻技藝熟練，用於肉品較為恰當。(C)「齒頰留香」形容食物味道鮮美。(D)「為民喉舌」為民意代表祝賀詞。", "trans": "", "per": {"A": "「妙手回春」為醫界祝賀詞。", "B": "「庖丁解牛」比喻技藝熟練，用於肉品較為恰當。", "C": "「齒頰留香」形容食物味道鮮美。", "D": "「為民喉舌」為民意代表祝賀詞。"}, "psg": "", "need_img": false, "imgs": [["", "img/身為魚販/2fcf52418693afb0.png"]]}, {"n": 19, "ans": "A", "stem": "「魚」為常見漢字，歷經演變成為今日形體。請閱讀下文，依序填入對應的答案：", "opts": [["A", "①②③字形見表；④象形"], ["B", "①②③字形見表；④會意"], ["C", "①②③字形見表；④指事"], ["D", "①②③字形見表；④假借"]], "exp": "「魚」字源於象形，最早出現在甲骨文，可見形似一條完整的魚，包括魚頭、魚身、魚尾及魚鰭。隨著時間推移，字形逐漸簡化，演變成篆書（省了魚鰭）、隸書（以四點代表魚尾），再到如今的楷書，故選(A)。", "trans": "", "per": {"A": "「魚」字源於象形，最早出現在甲骨文，可見形似一條完整的魚，包括魚頭、魚身、魚尾及魚鰭。隨著時間推移，字形逐漸簡化，演變成篆書（省了魚鰭）、隸書（以四點代表魚尾），再到如今的楷書，故選(A)。"}, "psg": "甲骨文（①）的樣貌，以直式呈現，上像魚頭，中像身、鱗，下像尾，兩側像鰭；篆文（②）的樣貌和戰國文字相近，省了魚鰭；字經隸書，變形為（③）的樣貌，以四點代表魚尾，頗失其形，而楷書沿之而定體，故此字造字法則為（④）。<div class='aq-src'>（改寫自《中華語文知識庫》）</div>", "need_img": false, "imgs": [["", "img/身為魚販/2495101649bb7217.png"]]}, {"n": 20, "ans": "C", "stem": "下列關於林楷倫的敘述，何者正確", "opts": [["A", "曾從事漁撈業，執行鯨豚海上生態調查"], ["B", "退休後開始販魚，並籌辦黑潮海洋文教基金會以倡導生態保育"], ["C", "創作多以散文的方式呈現，書寫販魚的知識及對生命的省思"], ["D", "一生致力於原住民的文學創作，首先創辦原住民刊物《獵人文化》"]], "exp": "(A)目前從事販魚業，並未執行鯨豚海上生態調查。(B)黑潮海洋文教基金會是廖鴻基所籌辦。(D)他並非原住民，《獵人文化》是由瓦歷斯．諾幹所創辦。", "trans": "", "per": {"A": "目前從事販魚業，並未執行鯨豚海上生態調查。", "B": "黑潮海洋文教基金會是廖鴻基所籌辦。", "D": "他並非原住民，《獵人文化》是由瓦歷斯．諾幹所創辦。"}, "psg": "", "need_img": false}, {"n": 21, "ans": "A", "stem": "依據上文關於鰻魚的敘述，下列何者正確", "opts": [["A", "鰻魚苗俗稱「白金」，具有極高的經濟價值"], ["B", "臺灣的鰻魚苗完全仰賴進口，無法自行繁殖"], ["C", "2010 年初臺灣的鰻魚產量有將近 1／6 以上的成長，價格隨之上揚"], ["D", "日本鰻通常產卵於大西洋深海中，孵化後自行游至臺灣河口進行繁殖"]], "exp": "(B)鰻魚苗為漁民自行在臺灣河口捕捉。 (C)鰻魚產量在 2010 年初銳減至過往的 1/6。 (D)產卵於太平洋深海中。", "trans": "", "per": {"B": "鰻魚苗為漁民自行在臺灣河口捕捉。", "C": "鰻魚產量在 2010 年初銳減至過往的 1/6。", "D": "產卵於太平洋深海中。"}, "psg": "　　十多年前冬季，筆者拜訪蘭陽溪口，目睹漁民捕撈鰻魚苗的盛況。漁民用手罟在黑夜中捕撈被稱為「白金」的鰻魚苗，清晨與盤商交易，好的時候一晚收入數萬。如今，由於攔河漁網的使用和鰻魚資源的減少，漁民一晚僅能賺取數千元。<br><br>　　鰻魚變得珍貴的主因在於其產量自 2010 年初銳減至過往的六分之一。鰻魚養殖技術雖發達，但至今無法人工繁殖。日本鰻於夏季在太平洋深海產卵，孵化成幼苗後，順海流漂至臺灣河口，在冬季溯溪而上，經數年成長後再回到海中繁殖。<br><br>　　臺灣海域魚類種類占全球總數的十分之一，其中一半的洄游性魚類造訪臺灣。這些資源來自全球海洋，而臺灣對河川和海洋的破壞也會影響全球漁業。<br><br>　　在魚類資源未消失前，我們應從餐桌做起，依照時令選擇適當的海鮮食材，為海洋資源的永續發展盡一分心力。季節性的選擇如冬天的烏魚，正是保護資源的重要方式。<table class='jy-table' style='margin-top:12px'><tr><th class='jy-th'>建議食用季節</th><td><b>春</b></td><td><b>夏</b></td><td><b>秋</b></td><td><b>冬</b></td></tr><tr><th class='jy-th'>漁撈海鮮</th><td>金線魚、白鯧、蝦姑、午仔、章魚、赤鯮、水母、四破</td><td>蝦姑、午仔、白帶魚、章魚、梭仔蟹、水母、四破、竹筴魚</td><td>鎖管、梭仔蟹、秋刀魚、鯖魚、水母</td><td>鯖魚、肉鯽仔、土魠、花枝、烏魚、水母</td></tr></table><div class='aq-src'>（改寫自方韻如〈別傻了，這不只是平抑魚價的問題〉，2010/12/20 環境資訊中心））</div>", "need_img": false}, {"n": 22, "ans": "D", "stem": "翰林餐廳在年終時舉辦尾牙宴以犒賞員工，依據上文，下列何者最適合成為宴會上的菜餚", "opts": [["A", "紅燒金線魚"], ["B", "燒烤秋刀魚"], ["C", "蔥爆梭仔蟹"], ["D", "清蒸烏魚"]], "exp": "由「年終」可知為冬天，故選(D)。(A)春天。(B)秋天。(C)夏天、秋天。", "trans": "", "per": {"A": "春天。", "B": "秋天。", "C": "夏天、秋天。", "D": "由「年終」可知為冬天，故選(D)。"}, "psg": "　　十多年前冬季，筆者拜訪蘭陽溪口，目睹漁民捕撈鰻魚苗的盛況。漁民用手罟在黑夜中捕撈被稱為「白金」的鰻魚苗，清晨與盤商交易，好的時候一晚收入數萬。如今，由於攔河漁網的使用和鰻魚資源的減少，漁民一晚僅能賺取數千元。<br><br>　　鰻魚變得珍貴的主因在於其產量自 2010 年初銳減至過往的六分之一。鰻魚養殖技術雖發達，但至今無法人工繁殖。日本鰻於夏季在太平洋深海產卵，孵化成幼苗後，順海流漂至臺灣河口，在冬季溯溪而上，經數年成長後再回到海中繁殖。<br><br>　　臺灣海域魚類種類占全球總數的十分之一，其中一半的洄游性魚類造訪臺灣。這些資源來自全球海洋，而臺灣對河川和海洋的破壞也會影響全球漁業。<br><br>　　在魚類資源未消失前，我們應從餐桌做起，依照時令選擇適當的海鮮食材，為海洋資源的永續發展盡一分心力。季節性的選擇如冬天的烏魚，正是保護資源的重要方式。<table class='jy-table' style='margin-top:12px'><tr><th class='jy-th'>建議食用季節</th><td><b>春</b></td><td><b>夏</b></td><td><b>秋</b></td><td><b>冬</b></td></tr><tr><th class='jy-th'>漁撈海鮮</th><td>金線魚、白鯧、蝦姑、午仔、章魚、赤鯮、水母、四破</td><td>蝦姑、午仔、白帶魚、章魚、梭仔蟹、水母、四破、竹筴魚</td><td>鎖管、梭仔蟹、秋刀魚、鯖魚、水母</td><td>鯖魚、肉鯽仔、土魠、花枝、烏魚、水母</td></tr></table><div class='aq-src'>（改寫自方韻如〈別傻了，這不只是平抑魚價的問題〉，2010/12/20 環境資訊中心））</div>", "need_img": false}, {"n": 23, "ans": "C", "stem": "依據上文，可推知「依照時令選擇適當的海鮮食材」是使海洋資源永續發展的關鍵，此行為的內涵與下列何者最接近", "opts": [["A", "小不忍則亂大謀"], ["B", "塞翁失馬，焉知非福"], ["C", "斧斤以時入山林"], ["D", "如臨深淵，如履薄冰"]], "exp": "依「資源永續發展」的概念可知選 (C)依照樹木生存的時機進行砍伐，較符合資源永續發展的精神。 (A)小細節上不能忍耐，就容易壞了全盤大計。 (B)比喻禍福時常互轉，不能以一時論定。(D)比喻小心謹慎的樣子。", "trans": "(C)依照時令，才拿著伐木的工具進入山林砍伐。《孟子．梁惠王》上。(D)好像走到深水潭邊及薄冰上。《詩經．小雅》。", "per": {"C": "依照樹木生存的時機進行砍伐，較符合資源永續發展的精神。", "A": "小細節上不能忍耐，就容易壞了全盤大計。", "B": "比喻禍福時常互轉，不能以一時論定。", "D": "比喻小心謹慎的樣子。"}, "psg": "　　十多年前冬季，筆者拜訪蘭陽溪口，目睹漁民捕撈鰻魚苗的盛況。漁民用手罟在黑夜中捕撈被稱為「白金」的鰻魚苗，清晨與盤商交易，好的時候一晚收入數萬。如今，由於攔河漁網的使用和鰻魚資源的減少，漁民一晚僅能賺取數千元。<br><br>　　鰻魚變得珍貴的主因在於其產量自 2010 年初銳減至過往的六分之一。鰻魚養殖技術雖發達，但至今無法人工繁殖。日本鰻於夏季在太平洋深海產卵，孵化成幼苗後，順海流漂至臺灣河口，在冬季溯溪而上，經數年成長後再回到海中繁殖。<br><br>　　臺灣海域魚類種類占全球總數的十分之一，其中一半的洄游性魚類造訪臺灣。這些資源來自全球海洋，而臺灣對河川和海洋的破壞也會影響全球漁業。<br><br>　　在魚類資源未消失前，我們應從餐桌做起，依照時令選擇適當的海鮮食材，為海洋資源的永續發展盡一分心力。季節性的選擇如冬天的烏魚，正是保護資源的重要方式。<table class='jy-table' style='margin-top:12px'><tr><th class='jy-th'>建議食用季節</th><td><b>春</b></td><td><b>夏</b></td><td><b>秋</b></td><td><b>冬</b></td></tr><tr><th class='jy-th'>漁撈海鮮</th><td>金線魚、白鯧、蝦姑、午仔、章魚、赤鯮、水母、四破</td><td>蝦姑、午仔、白帶魚、章魚、梭仔蟹、水母、四破、竹筴魚</td><td>鎖管、梭仔蟹、秋刀魚、鯖魚、水母</td><td>鯖魚、肉鯽仔、土魠、花枝、烏魚、水母</td></tr></table><div class='aq-src'>（改寫自方韻如〈別傻了，這不只是平抑魚價的問題〉，2010/12/20 環境資訊中心））</div>", "need_img": false, "appraise": "本文透過鰻魚的價格上漲，對比十年前與十年後的臺灣海洋資源的榮枯，試圖喚起讀者對於臺灣豐饒漁產的想像，並期許消費者能依照時令選擇適當的海鮮食材，使海洋資源能夠永續存有與發展。"}, {"n": 24, "ans": "B", "stem": "從敘事者（說話者）的角度出發，可以更容易理解觀點。下列關於 (甲)文的理解，何者最適當", "opts": [["A", "敘事者感到無法擺脫魚販身分，始終有強烈排斥、難以接受的心理"], ["B", "敘事者從抗拒到接受自己的職業，並透過環境與人際互動認同自我"], ["C", "敘事者認為應該與過去魚販身分劃清界線，去追求不同的人生道路"], ["D", "魚販的世界雖喧囂而熱鬧，但敘事者始終感到隔閡而無法融入其中"]], "exp": "敘事者從最初的某種抗拒，逐漸轉變為接受，並透過與市場環境和人群的互動，最終認同了自己的魚販身分，故選 (B)。 (A)敘事者未始終強烈排斥與難以接受。 (C)文中未提及要劃清界線或追求人生道路。(D)敘事者已融入市場環境，並非感到隔閡。", "trans": "", "per": {"A": "敘事者未始終強烈排斥與難以接受。", "C": "文中未提及要劃清界線或追求人生道路。", "D": "敘事者已融入市場環境，並非感到隔閡。", "B": "敘事者從最初的某種抗拒，逐漸轉變為接受，並透過與市場環境和人群的互動，最終認同了自己的魚販身分，故選 (B)。"}, "psg": "(甲)　我以為洗去身上的魚味，穿上怎樣的服裝，又能變成怎樣的人。但作為魚販，是黏著在皮膚上的魚鱗，沒有感覺便嵌在那，①<u>覺得癢的時候想拔下那些魚鱗，才發現體膚已經有不一樣的顏色了</u>。<br>　　凌晨兩三點的高速公路，沒什麼車，通往那時最熱鬧的地方：魚市。嘈雜到嗓門加大，氣味紛雜，聞不出魚臭，千百盞燈照出的世界已無黑暗。我下了貨車，踏入潮溼，邊走邊點頭或是捶打他人手臂，幾句髒話，都只是招呼。當我習慣這些生活，我就接受了自己是名魚販。②<u>魚販中，有幾個跟我相似的年輕人，有老派如阿公的人；有幾個會讓人想起誰，有幾個是他自己的模樣</u>。<div class='aq-src'>（節錄自林楷倫〈身為魚販〉）</div><br>(乙)　那麼，究竟有什麼內在驅力促使我們講出自己的故事來呢？首先，正因為人是有限存在，是朝向死亡的存在，因此在這個喧嘩世界中，在熙熙攘攘的日常瑣碎當中，我們都盡量試圖證明自己的存在價值，力圖保留且紀念自己生命歷程的各種記憶與意義。<br>　　而自我敘事就是證明、紀念與重建自我存有意義的有效途徑。簡言之，自我敘事是一種生命意志的表現，是在有限的存在條件下努力創造出無限的可能性的意義製造實踐。<br>　　看起來普普通通的種種私人故事，皆是把自身的生命經驗重新連結於整個生活世界的一座天橋，也就是打通人與世界、個體與集體、普遍與特殊之間的關係脈絡的重整方案。透過說故事的方式，我們對自己人生進行一番詮釋，從而開始一場理解、認知與評估自己生命價值的反思之旅。<div class='aq-src'>（節錄自徐敬官〈書寫你的生命故事：自我敘事與身分認同〉）</div>", "need_img": false}, {"n": 25, "ans": "D", "stem": "依據 (乙)文的觀點，自我敘事的意義為何", "opts": [["A", "提供他人能理解人生樣貌，進而能讓世界更美好"], ["B", "透過描述自己故事，彰顯獨特感與社會產生距離"], ["C", "總結生活經驗的樣態，讓自我價值交由他人詮釋"], ["D", "幫助個人記錄生命，並讓經驗具有更深層的價值"]], "exp": "(A)重點在自我理解，不是讓世界更美好。(B)強調與世界建立連結，而非產生距離。(C)自我敘事是個人（自身）詮釋，而非交由他人決定價值。", "trans": "", "per": {"A": "重點在自我理解，不是讓世界更美好。", "B": "強調與世界建立連結，而非產生距離。", "C": "自我敘事是個人（自身）詮釋，而非交由他人決定價值。"}, "psg": "(甲)　我以為洗去身上的魚味，穿上怎樣的服裝，又能變成怎樣的人。但作為魚販，是黏著在皮膚上的魚鱗，沒有感覺便嵌在那，①<u>覺得癢的時候想拔下那些魚鱗，才發現體膚已經有不一樣的顏色了</u>。<br>　　凌晨兩三點的高速公路，沒什麼車，通往那時最熱鬧的地方：魚市。嘈雜到嗓門加大，氣味紛雜，聞不出魚臭，千百盞燈照出的世界已無黑暗。我下了貨車，踏入潮溼，邊走邊點頭或是捶打他人手臂，幾句髒話，都只是招呼。當我習慣這些生活，我就接受了自己是名魚販。②<u>魚販中，有幾個跟我相似的年輕人，有老派如阿公的人；有幾個會讓人想起誰，有幾個是他自己的模樣</u>。<div class='aq-src'>（節錄自林楷倫〈身為魚販〉）</div><br>(乙)　那麼，究竟有什麼內在驅力促使我們講出自己的故事來呢？首先，正因為人是有限存在，是朝向死亡的存在，因此在這個喧嘩世界中，在熙熙攘攘的日常瑣碎當中，我們都盡量試圖證明自己的存在價值，力圖保留且紀念自己生命歷程的各種記憶與意義。<br>　　而自我敘事就是證明、紀念與重建自我存有意義的有效途徑。簡言之，自我敘事是一種生命意志的表現，是在有限的存在條件下努力創造出無限的可能性的意義製造實踐。<br>　　看起來普普通通的種種私人故事，皆是把自身的生命經驗重新連結於整個生活世界的一座天橋，也就是打通人與世界、個體與集體、普遍與特殊之間的關係脈絡的重整方案。透過說故事的方式，我們對自己人生進行一番詮釋，從而開始一場理解、認知與評估自己生命價值的反思之旅。<div class='aq-src'>（節錄自徐敬官〈書寫你的生命故事：自我敘事與身分認同〉）</div>", "need_img": false}, {"n": 26, "ans": "B", "stem": "若以(乙)文觀點，印證(甲)文的敘述，下列說明何者最不適當", "opts": [["A", "(甲)文文句①：說故事的人是在對自己的人生進行詮釋"], ["B", "(甲)文文句①：說故事的人用意在記錄朝向死亡的世界"], ["C", "(甲)文文句②：說故事的人在理解他人中，評估自己生命的價值"], ["D", "(甲)文文句②：說故事的人打通自己與群體的關係，形成連結"]], "exp": "(B)文句①在理解、認知與評估自我，與死亡無直接關聯，故最不適當。(A)文句①是對自己魚販人生的詮釋。(C)透過觀察他人，文句②確實在評估自己的生命價值。(D)文句②呈現作者透過觀察魚販群體的不同面貌，看見自己身分在其中的位置，形成與群體的生命經驗連結，此與(乙)文所說「自我敘事能連結個體與生活世界」的觀點相符。", "trans": "", "per": {"B": "文句①在理解、認知與評估自我，與死亡無直接關聯，故最不適當。", "A": "文句①是對自己魚販人生的詮釋。", "C": "透過觀察他人，文句②確實在評估自己的生命價值。", "D": "文句②呈現作者透過觀察魚販群體的不同面貌，看見自己身分在其中的位置，形成與群體的生命經驗連結，此與(乙)文所說「自我敘事能連結個體與生活世界」的觀點相符。"}, "psg": "(甲)　我以為洗去身上的魚味，穿上怎樣的服裝，又能變成怎樣的人。但作為魚販，是黏著在皮膚上的魚鱗，沒有感覺便嵌在那，①<u>覺得癢的時候想拔下那些魚鱗，才發現體膚已經有不一樣的顏色了</u>。<br>　　凌晨兩三點的高速公路，沒什麼車，通往那時最熱鬧的地方：魚市。嘈雜到嗓門加大，氣味紛雜，聞不出魚臭，千百盞燈照出的世界已無黑暗。我下了貨車，踏入潮溼，邊走邊點頭或是捶打他人手臂，幾句髒話，都只是招呼。當我習慣這些生活，我就接受了自己是名魚販。②<u>魚販中，有幾個跟我相似的年輕人，有老派如阿公的人；有幾個會讓人想起誰，有幾個是他自己的模樣</u>。<div class='aq-src'>（節錄自林楷倫〈身為魚販〉）</div><br>(乙)　那麼，究竟有什麼內在驅力促使我們講出自己的故事來呢？首先，正因為人是有限存在，是朝向死亡的存在，因此在這個喧嘩世界中，在熙熙攘攘的日常瑣碎當中，我們都盡量試圖證明自己的存在價值，力圖保留且紀念自己生命歷程的各種記憶與意義。<br>　　而自我敘事就是證明、紀念與重建自我存有意義的有效途徑。簡言之，自我敘事是一種生命意志的表現，是在有限的存在條件下努力創造出無限的可能性的意義製造實踐。<br>　　看起來普普通通的種種私人故事，皆是把自身的生命經驗重新連結於整個生活世界的一座天橋，也就是打通人與世界、個體與集體、普遍與特殊之間的關係脈絡的重整方案。透過說故事的方式，我們對自己人生進行一番詮釋，從而開始一場理解、認知與評估自己生命價值的反思之旅。<div class='aq-src'>（節錄自徐敬官〈書寫你的生命故事：自我敘事與身分認同〉）</div>", "need_img": false, "appraise": "(乙)文中探討自我敘事的意義，強調人透過講述自身故事來確認存在價值，並在有限生命中創造意義。自我敘事連結個體與世界，使個人經驗獲得詮釋，進而促使理解與反思。文中透過哲理性的論述，說明個人故事如何成為與眾人共享生命經驗的橋梁。"}],"title": "當代 林楷倫〈身為魚販〉", "author": {"dynasty": "當代", "name": "林楷倫", "intro": "", "context": "本文節選自偽魚販指南一書，偽，偽裝，指的是作者一開始並非自願當魚販；指南，辨別方向或解決問題的參考資料、途徑，此指作者生活的片段。作者回憶童年時，祖父是魚販，父母曾經營飲料店，後因父親沉溺賭博，賠掉婚姻與事業，導致他在國中時便開始幫忙家中賣魚。"}, "extras": {"intro": [{"label": "題解·課本", "head": "題解", "body": "本文節選自偽魚販指南一書，偽，偽裝，指的是作者一開始並非自願當魚販；指南，辨別方向或解決問題的參考資料、途徑，此指作者生活的片段。作者回憶童年時，祖父是魚販，父母曾經營飲料店，後因父親沉溺賭博，賠掉婚姻與事業，導致他在國中時便開始幫忙家中賣魚。<br><br>身為魚販一文記錄作者投身魚市，最後成為真正魚販的心路歷程。原本他希望透過教育翻轉自己的人生，但父親持續積欠高額賭債，作者只能無奈的放棄學業，成為一名專職魚販。<br><br>成為魚販的過程中，作者學會從容面對現實，在混亂、疲憊的步調裡，摸索出規則。對世事的領悟從懵懂到透澈，最後坦然接受，提供讀者對生命的省思。"}], "authorPages": [{"label": "作者·課本", "head": "作者", "body": "林楷倫，臺中市霧峰區人，民國七十五年生。中臺科技大學五專部醫事技術系畢業。後曾就讀過銘傳大學、朝陽科技大學、東海大學與交通大學等校。現為專職魚販、作家。<br><br>對林楷倫而言，賣魚是不得已的選擇。但現在他努力賣魚，撐起家中經濟；認真寫作，描繪魚市所見。他認為賣魚是一分專業，各行各業都值得被尊重，魚販的人生也可以很精彩。<br><br>他的散文風格寫實又富戲劇張力，帶有小說筆法，內容兼具賣魚知識和生命自省，生動敘寫人情事理，使讀者更加了解這個行業。曾獲得林榮三文學獎、時報文學獎、臺北文學獎、臺中文學獎等。著有散文集《偽魚販指南》、《廚房裡的偽魚販》，短篇小說集《雪卡毒》。"}], "appreciation": [{"label": "賞析·課本", "head": "賞析", "body": "本文敘述作者成為魚販的歷程、感受及對生命的理解。寫作特色如下：<br><br>一、從剖魚到自剖，生命經驗的真實呈現：這是臺灣第一本真人實事的魚販寫作，作者凌晨在市場剖魚，學習一堂堂的魚販學，展開他的魚市人生。魚市下班後的空檔，寫作自剖，從家庭責任、個人夢想、身分價值等面向思索人生。讀者可從字裡行間感受到魚市的氣味、魚販與顧客間的人情交流，並對他們投以更多的理解與尊重。<br><br>二、筆法寫實富戲劇張力，兼具幽默與深度：作者描述魚市見聞，畫面生動，充滿戲劇張力。文字平易卻極具深度，幽默中略帶嘲諷戲謔，又不乏親切感。白描直述中注入濃烈的人生掙扎，沒有刻意逗笑的文句，卻能讓人情感激動，展現他的文字魅力。<br><br>三、面對生命困境，調整步伐重新出發：作者自小就想盡辦法擺脫宿命，雖卸不掉親情枷鎖，接受自己成為魚販，但正職是魚販的同時，作者將自己的遭遇、心情、對生命的反思，都訴諸文字，一步步實現自我成為作家。這樣的斜槓人生，是作者對命運的解鎖。透過本文，引導讀者遭遇挫折時，能有不同面向的思考。<br><br>文末，作者提到：「既然不愛的、討厭的都能做好，那還有什麼不能做呢？」「身為一名魚販，我很努力，很努力了。」在第三代魚販身上，散發出令人深思、動容的海洋鹹味，讓讀者看見黏滑微腥的生活樣貌，也看到人生充滿無限可能。"}], "supplement": [{"label": "題解·補充", "head": "書名「偽魚販指南」釋義", "body": "本文節選自《<b>偽魚販指南</b>》一書。<br><br><b>偽</b>：偽裝，指的是作者一開始並非自願當魚販。<br><b>指南</b>：辨別方向或解決問題的參考資料、途徑，此指作者生活的片段。"}, {"label": "題解·補充", "head": "寫作背景", "body": "作者回憶童年時，祖父是魚販，父母曾經營飲料店，後因父親沉溺賭博，賠掉婚姻與事業，導致他在國中時便開始幫忙家中賣魚。<br><br>〈身為魚販〉一文記錄作者投身魚市，最後成為真正魚販的心路歷程。原本他希望透過教育翻轉自己的人生，但父親持續積欠高額賭債，作者只能無奈的放棄學業，成為一名專職魚販。<br><br>成為魚販的過程中，作者學會從容面對現實，在混亂、疲憊的步調裡，摸索出規則。對世事的領悟從懵懂到透澈，最後坦然接受，提供讀者對生命的省思。"}, {"label": "作者·補充", "head": "作者生平", "body": "林楷倫，臺中市霧峰區人，民國七十五年生。中臺科技大學五專部醫事技術系畢業。後曾就讀過銘傳大學、朝陽科技大學、東海大學與交通大學等校。現為專職魚販、作家。<br><br>對林楷倫而言，賣魚是不得已的選擇。但現在他努力賣魚，撐起家中經濟；認真寫作，描繪魚市所見。他認為賣魚是一分專業，各行各業都值得被尊重，魚販的人生也可以很精彩。"}, {"label": "作者·補充", "head": "文學風格與成就", "body": "他的散文風格<b>寫實又富戲劇張力，帶有小說筆法</b>，內容兼具賣魚知識和生命自省，生動敘寫人情事理，使讀者更加了解這個行業。<br><br>曾獲得<b>林榮三文學獎、時報文學獎、臺北文學獎、臺中文學獎</b>等。著有散文集《偽魚販指南》《廚房裡的偽魚販》，短篇小說集《雪卡毒》。"}, {"label": "作者·補充", "head": "軼聞掌故", "body": "<b>1. 父親賭博賠掉身家</b>：父親沉溺賭博，賠掉婚姻與事業，作者國中起便幫忙賣魚。<br><b>2. 慶幸志願沒有成真</b>：原以醫檢師為志願，如今回望，反而慶幸走上不同的路。<br><b>3. 市場的稱呼</b>：在魚市裡，人們以攤位或魚種相稱，身分被工作吞沒。<br><b>4. 腰痛的職業病</b>：長年彎腰刨魚，落下腰疾。<br><b>5. 不像魚販的斜槓人生</b>：白天賣魚、夜裡寫作，兩種身分並行。<br><b>6. 兩次被父親背叛</b>：課文中「裝睡的人叫不醒」的沉痛體悟由此而來。"}, {"label": "補充·魚類知識", "head": "課文中的魚", "body": "<b>白鯧</b>：一般家庭常見的食用魚。<br><b>正鯧</b>：魚鰭長且魚尾如剪刀。<br><b>暗鯧</b>：體色偏灰、魚鰭短。<br><b>斗鯧</b>：魚鰭魚尾短短，鰭邊形狀如流蘇。<br><b>白口</b>：即銀彭納石首魚，鰓腔黑色、口腔白色。<br><b>黑喉</b>：屬石首魚科，鰓腔、口腔皆為黑色，棲息於砂泥底質較深海域。<br><b>肉魚</b>：即刺鯧、肉鯽魚，重要食用魚，野生數量穩定。<br><b>吳郭魚</b>：由臺籍日本兵吳振輝及郭啟彰引進；臺灣改良之養殖品系又特稱<b>臺灣鯛</b>。"}], "questions": [], "exams": [], "reviewQ": [{"q": "文中提到「阿公說賣魚要學，學一輩子。爸說賣魚要學，學一下子」，你贊同哪個說法？為什麼？", "a": "（開放作答，可依課文與生活經驗發揮）"}, {"q": "作者提及自己一步步成為魚販的過程，充滿無力與不得不的無奈。如果家人希望你將來從事某種工作，但跟你的生涯規劃有所牴觸時，你會怎麼做？為什麼？", "a": "（開放作答，可依課文與生活經驗發揮）"}]}, "textPages": [{"seg": "第一段", "title": "第一段", "book": "課本 P.8~P.9", "noteStart": 1, "lines": [{"text": "每個週末，我顧起魚攤的蛤、蚵、魚，攤位上的魚我只認得白鯧、肉魚、吳郭魚。我問爸，爸叫我問阿公。", "ask": ["這一段寫到哪些<b>具體</b>的工作？", "作者在魚攤上，是<b>幫忙</b>還是<b>工作</b>？"], "askT": "開場後的第一段。先讓學生說出具體事物（蛤、蚵、魚、白鯧、肉魚、吳郭魚），再問「他認得的魚很少，這代表什麼？」——他是新手，從零開始學。", "cite": "攤位上的魚我只認得白鯧、肉魚、吳郭魚", "mean": "作者對魚類的認識有限", "cite2": "我問爸，爸叫我問阿公", "mean2": "暗示阿公的經驗與知識更為豐富", "rhet": [["頂真", "<span class=\"tp-rq\">我問<b class='rq-hi'>爸</b>，<b class='rq-hi'>爸</b>叫我問阿公</span>"]]}, {"text": "阿公拿起冷凍與{n:1|現流}的白鯧，教我看背上的藍色與鱗片上的微微虹光分辨鮮度，教我從魚鰭魚尾分辨不同品種的白鯧：魚鰭長且魚尾如剪刀的，是正鯧；體色偏灰、魚鰭短的是暗鯧；魚鰭、魚尾短短，鰭邊形狀如流蘇是斗鯧。他問我哪種好吃，我說正鯧，暗鯧與斗鯧偏軟。阿公稱讚{n:2|嘴刁}的我，又拿起白口與黑喉。", "cite": "阿公稱讚嘴刁的我", "mean": "阿公對作者的品味表示讚賞，稱讚他的辨識能力", "rhet": [["類疊", "<span class=\"tp-rq\"><b class='rq-hi'>教我</b>看背上的藍色與鱗片上的微微虹光分辨鮮度，<b class='rq-hi'>教我</b>從魚鰭魚尾分辨不同品種的白鯧</span>"], ["明喻", "<span class=\"tp-rq\">魚鰭長且魚尾如剪刀</span>"], ["明喻", "<span class=\"tp-rq\">鰭邊形狀如流蘇</span>"]]}, {"text": "每個週末不去私立國中的輔導課，在魚攤上生物課。蝦不選紅頭，小卷不選紅身。春末吃海蛤，養殖蛤不選脫皮，臺灣蚵不能賣綠肚。", "cite": "在魚攤上生物課", "mean": "作者將在魚攤上的工作經驗視為生物學的學習過程", "cite2": "蝦不選紅頭，小卷不選紅身。春末吃海蛤，養殖蛤不選脫皮，臺灣蚵不能賣綠肚", "mean2": "列出挑選海鮮的具體標準，暗示阿公的專業知識豐富", "rhet": [["類疊", "<span class=\"tp-rq\">蝦<b class='rq-hi'>不選</b>紅頭，小卷<b class='rq-hi'>不選</b>紅身。春末吃海蛤，養殖蛤<b class='rq-hi'>不選</b>脫皮</span>"]]}, {"text": "這是阿公魚攤的第一學期。", "cite": "這是阿公魚攤的第一學期", "mean": "「第一學期」暗示這是作者在魚攤上學習的起點，強調這段經歷對他成長的重要性"}, {"text": "沒有生來就會賣魚的人。阿公說賣魚要學，學一輩子。", "ask": ["同樣一句「賣魚要學」，阿公和爸差在哪<b>三個字</b>？", "這三個字的差別，代表他們怎麼看這份工作？", "作者後來比較像誰？"], "askT": "<b>本課第一個關鍵句。</b><br>阿公當它是<b>一門手藝</b>（學一輩子），爸當它是<b>退路</b>（學一下子）。作者夾在中間。<br><br>可以問：「如果你要接家裡的工作，你希望聽到哪一句？」", "cite": "沒有生來就會賣魚的人", "mean": "強調賣魚需要持續學習，沒有人天生就會這項技能", "cite2": "阿公說賣魚要學，學一輩子。爸說賣魚要學，學一下子。他們都說以後不要賣魚，好好讀書", "mean2": "阿公和爸爸對賣魚的學習有不同的觀點，但同時都希望作者專注於課業上的學習", "rhet": [["類疊", "<span class=\"tp-rq\">阿公說<b class='rq-hi'>賣魚要學</b>，學一輩子。爸說<b class='rq-hi'>賣魚要學</b>，學一下子</span>"], ["映襯", "<span class=\"tp-rq\">阿公說賣魚要學，學<b class='rq-hi'>一輩子</b>。爸說賣魚要學，學<b class='rq-hi'>一下子</b></span>"], ["頂真", "<span class=\"tp-rq\">賣魚要<b class='rq-hi'>學</b>，<b class='rq-hi'>學</b>一輩子</span>"]]}, {"text": "爸說賣魚要學，學一下子。", "rhet": [["類疊", "<span class=\"tp-rq\">阿公說<b class='rq-hi'>賣魚要學</b>，學一輩子。爸說<b class='rq-hi'>賣魚要學</b>，學一下子</span>"], ["映襯", "<span class=\"tp-rq\">阿公說賣魚要學，學<b class='rq-hi'>一輩子</b>。爸說賣魚要學，學<b class='rq-hi'>一下子</b></span>"], ["頂真", "<span class=\"tp-rq\">賣魚要<b class='rq-hi'>學</b>，<b class='rq-hi'>學</b>一下子</span>"]]}, {"text": "他們都說以後不要賣魚，好好讀書。"}], "notes": [["現流", "閩南語，即「現流仔」，指漁民剛從海潮捕撈上岸而未經冷凍的新鮮海產。「流」，此指潮水。"], ["嘴刁", "指吃東西挑剔，過分講究。"]], "pian": "第一段：作者在週末到家族魚攤協助賣魚，並學習相關知識，家人則希望他好好讀書。", "xi": "作者透過簡單的對話，表達對魚類的認識有限，在魚攤上經由阿公的教導，展現其學習的心態，同時反映出家庭成員間的互動。", "fan": "", "qa": [["阿公教作者分辨魚的鮮度時，提到哪些辨識方法？（擷取訊息）", "看魚「背上的藍色」和「鱗片上的微微虹光」來分辨鮮度。"], ["阿公教作者三種不同鯧魚分辨的特徵是什麼？（擷取訊息）", "正鯧：魚鰭長且魚尾如剪刀。<br>暗鯧：體色偏灰，魚鰭短。<br>斗鯧：魚鰭和魚尾短，鰭邊形狀如流蘇。"], ["作者在魚攤上學習了哪些挑選海鮮的知識？（擷取訊息）", "(1)蝦不選紅頭；(2)小卷不選紅身；(3)春末吃海蛤；(4)養殖蛤不選脫皮；(5)臺灣蚵不能賣綠肚。"], ["作者為何把在魚攤上學習的經歷形容為上「生物課」？（文意推論）", "作者在魚攤上學到魚類的相關知識，這些知識與生物學的內容相似。"], ["阿公和爸爸對於學習賣魚有什麼不同的看法？反映出什麼不同的態度？（擷取訊息／文意推論）", "阿公認為賣魚要學，學一輩子；爸爸認為賣魚要學，只需學一下子。阿公的看法反映對職業的尊重及認真的態度；爸爸的看法則反映出他並未全心投入販魚工作。"], ["作者的家人希望他「好好讀書」，可能是什麼原因？（文意推論）", "希望作者能有更好的未來和更高的社會地位，也反映他們對傳統職業的偏見。"]], "ask": ["圈出<b>作者在魚攤上實際做了哪些事</b>"], "askT": "<b>第1節 12–25′</b>　分段朗讀，逐段提示：<br>· 「這一段寫到哪些<b>具體</b>工作？」<br>· 「哪個詞句讓你感覺到辛苦或繁複？」<br>· 「這是作者<b>直接說明</b>，還是透過<b>動作、場景</b>讓我們看見？」<br><br><b>巡視時問：</b>「你圈的是工作<b>動作</b>，還是作者的<b>感受</b>？」"}, {"seg": "第二段", "title": "第二段", "book": "課本 P.9~P.11", "noteStart": 3, "lines": [{"text": "週末賣魚很累，上課變成放假，同學說你都不用假日輔導真好，我回說要不然你來賣魚。「才不要咧，很臭。」對，很臭，我聞到我的前臂仍有魚的血味。當他們這樣回時，我會將手掌摀住同學的嘴，說：「很臭嗎？」手拿開，他說臭死了，接下來都是國中生的垃圾話。", "rhet": [["摹寫（嗅覺）", "<span class=\"tp-rq\">我會將手掌摀住同學的嘴</span>──以身體動作寫出魚販之子在校園中被辨識、被排除的處境。"]], "ask": ["他為什麼摀的是<b>別人的嘴</b>，不是自己的手？", "這句有出現「丟臉」兩個字嗎？那我們怎麼知道他丟臉？"], "askT": "<b>本課第二個關鍵句。</b><br>沒說羞恥，但寫的是羞恥。他摀的不是自己的手，是<b>別人的嘴</b>——「怕被聞到」和「怕被說」同時寫進去了。<br><br><span class='ls-warn'>第三節作文課會回來用這句當範例：<b>不說感受，寫出畫面</b>。</span>", "cite": "我回說要不然你來賣魚。「才不要咧，很臭。」對，很臭，我聞到我的前臂仍有魚的血味。當他們這樣回時，我會將手掌摀住同學的嘴，說：「很臭嗎？」手拿開，他說臭死了，接下來都是國中生的垃圾話", "mean": "用幽默的方式回應同學的嘲諷，並透過肢體互動展現國中生的社交樣貌"}, {"text": "國中時，在魚攤的工作是把魚拿給阿公秤，或是按按磅秤跟客人說價錢，沒多做其他的工作。因為我不想當魚販，不想多踏一步，踏到殺魚的臺前，拿起魚{n:3|刨鱗}，剪刀剪開魚的皮肉。這些不想，我沒有說出口。", "cite": "不想當魚販，不想多踏一步，踏到殺魚的臺前", "mean": "對於成為魚販的抗拒與逃避", "rhet": [["類疊", "<span class=\"tp-rq\"><b class='rq-hi'>不想</b>當魚販，<b class='rq-hi'>不想</b>多踏一步</span>"]]}, {"text": "「你是魚販之子啊，得努力一點，不管你是單親還是什麼，你要為你的身分爭一口氣啊。」當時的導師這樣跟我說，埋入了什麼責任又什麼身分的。我的成績還過得去，便沒人管我要不要出席假日輔導。我的假日起得比上課還早，在空蕩無人的清晨市場等到{n:4|熱絡}，像上課鐘響，只不過我是魚攤上的學徒，被人叫喊。", "cite": "「你是魚販之子啊，得努力一點，不管你是單親還是什麼，你要為你的身分爭一口氣啊。」", "mean": "導師的期許，希望作者不要因為身分背景而妄自菲薄", "cite2": "我的假日起得比上課還早，在空蕩無人的清晨市場等到熱絡，像上課鐘響，只不過我是魚攤上的學徒，被人叫喊", "mean2": "假日清晨市場的描寫，顯現作者對魚販工作的承受"}, {"text": "「很爽喔。」同學常在禮拜一對我說。我又聞了我的手掌。"}, {"text": "只有我缺席的假日輔導，教室的空氣好了一些。", "cite": "只有我缺席的假日輔導，教室的空氣好了一些", "mean": "因作者缺席，所以不會將身上的魚腥味帶到教室；同時亦強調與同學間的疏離，因作者的缺席，反而讓教室空氣好一些"}, {"text": "「幹麼賣魚啦？」臉素淨、頭髮抹上髮膠的男孩問過我。他約我出遊，我不曾說好，每次都說要幫家裡。「真的很孝順欸你。」我笑笑無語。我與他在某個假日午後出遊，忘記去哪了，只記得沒睡午覺的疲憊讓我的臉漲紅，天色都沒暗，就說我要回家了。", "cite": "「真的很孝順欸你。」我笑笑無語", "mean": "對同學的讚美感到無言，因為是一種無奈與疲憊"}, {"text": "久了，就沒人問也沒人約。甚至畢業典禮那天，也沒人問我下午要去哪。往我家方向的站牌，無人等車；對面往城市的站牌，排滿了同學，沒有一個人向我招手。他們坐上一班車，另一群再坐上另一班，直到我等的公車來到。我坐在最後一排五人的座位，中間只有我一人。", "cite": "往我家方向的站牌，無人等車；對面往城市的站牌，排滿了同學，沒有一個人向我招手", "mean": "透過獨自等公車呈現孤獨與落寞", "cite2": "我坐在最後一排五人的座位，中間只有我一人", "mean2": "強調作者與周圍人群的疏離", "rhet": [["類疊", "<span class=\"tp-rq\">就<b class='rq-hi'>沒人</b>問也<b class='rq-hi'>沒人</b>約。甚至畢業典禮那天，也<b class='rq-hi'>沒人</b>問我</span>"], ["映襯", "<span class=\"tp-rq\">往我家方向的站牌，無人等車；對面往城市的站牌，排滿了同學</span>"]]}, {"text": "我睡了又醒，熟悉的路，醒了又睡，直到過站。走了回去。", "cite": "我睡了又醒，熟悉的路，醒了又睡，直到過站。走了回去", "mean": "暗示對當前生活狀態的無奈與迷茫"}, {"text": "就算要大考了，前兩個禮拜我還站在攤位前招呼客人，缺席賣魚還會覺得愧疚。我以為我有想過未來，以為我念了較自由的五專，選了醫事技術系，考上證照成為{n:5|檢驗師}，未來便能離開魚攤。但五專的課程更鬆，我刻意排出早上空堂、下午滿堂的課表，空堂時，在魚攤自學魚之{n:6|解剖學}、魚類辨識課。", "cite": "我以為我有想過未來，以為我念了較自由的五專，選了醫事技術系，考上證照成為檢驗師，未來便能離開魚攤", "mean": "表達對未來的期望與計畫，連續的「以為」，隱含不安與對現實的掙扎", "rhet": [["類疊", "<span class=\"tp-rq\">我<b class='rq-hi'>以為</b>我有想過未來，<b class='rq-hi'>以為</b>我念了較自由的五專</span>"], ["映襯", "<span class=\"tp-rq\">早上空堂、下午滿堂</span>"]]}], "notes": [["刨鱗", "刮除魚體上的鱗片。"], ["熱絡", "感情融洽，往來頻繁。此指人潮多，熱鬧的樣子。"], ["檢驗師", "為醫院內的專業醫事人員，負責檢驗檢體，以做為醫師診斷治療的重要依據。"], ["解剖學", "研究生物體的結構和組織的一門科學。"]], "pian": "第二段：作者敘述工作內容及與同學疏離的無奈，並自我期許透過讀書來掙脫賣魚的宿命。", "xi": "作者賣魚過程的辛苦，及與同學間的疏離，透過導師對自己的期望、同學對他的羨慕及稱讚，反思自我身分的價值，並期許透過讀書能翻轉魚販第三代的宿命。", "fan": "", "qa": [["國中時，作者在魚攤上主要負責哪些工作？（擷取訊息）", "把魚拿給阿公秤重，或是按按磅秤告訴客人價錢。"], ["畢業典禮當天，作者獨自一人坐車回家，推敲他內心的想法為何？（文意推論）", "由於平日推掉同學的邀約，導致沒有人約，此時作者的內心應該感到孤單與被忽略，並充滿無奈。"]], "ask": ["換一種顏色，圈出與<b>家庭、責任、期許</b>有關的內容"], "askT": "<b>第1節 25–35′</b>　照念：「我們不是要替作者貼標籤，也不是要猜測課文沒寫的事情。請<b>只根據文本</b>，找出作者面對的現實條件。」<br><br><b>接話：</b>「我們不是說有家庭責任就一定要接班。我們要看懂的是：作者的選擇<b>是在什麼條件下形成的</b>。」"}, {"seg": "第三段", "title": "第三段", "book": "課本 P.12~P.13", "noteStart": 7, "lines": [{"text": "我站在魚攤，拿起一尾尾冰冷的死魚，秤重刨鱗殺肚，換取更多更多的家庭奉獻。", "cite": "我站在魚攤，拿起一尾尾冰冷的死魚，秤重刨鱗殺肚，換取更多更多的家庭奉獻", "mean": "作者在魚攤努力工作，強調對家庭的責任與付出"}, {"text": "常有客人說我很乖，我不知道要怎麼壞。", "cite": "常有客人說我很乖，我不知道要怎麼壞", "mean": "對客人給予的讚美無法回應，是對自己身分與角色無從選擇的迷茫", "rhet": [["映襯", "<span class=\"tp-rq\">常有客人說我很乖，我不知道要怎麼壞</span>"]]}, {"text": "早上起床穿起雨鞋，橡膠的雨鞋{n:7|悶困}了腳，長襪勒緊了腿。久了，腿上有了一圈的黑線。那一圈腿上的黑線像卡在網縫間脫鱗的魚體。", "cite": "早上起床穿起雨鞋，橡膠的雨鞋悶困了腳，長襪勒緊了腿", "mean": "展現工作的辛苦與不適，更象徵工作的束縛", "cite2": "那一圈腿上的黑線像卡在網縫間脫鱗的魚體", "mean2": "腿部出現黑線，並將其比喻為卡在網縫間脫鱗的魚體，強調工作環境的艱苦和對身體的影響", "rhet": [["明喻", "<span class=\"tp-rq\">那一圈腿上的黑線像卡在網縫間脫鱗的魚體</span>"]]}, {"text": "中午換穿球鞋，上起自己毫無興趣的{n:8|微生物學}和化學，覺得人生不能這樣{n:9|虛耗}，卻耗了五年。五專畢業後，轉學考上北部的大學。剛上大學，阿公與爸又說週末沒人幫忙，能週週回來嗎？"}, {"text": "怎會說不能。半年後，週週臺北、臺中來回好累，轉回故鄉的大學。早上沒有課程，下午滿堂，「正職賣魚，讀書像放假」，我都這樣{n:10|自嘲}。那時，我已經能獨當一面站在魚攤前，招呼、買賣、殺魚，只差沒去{n:11|批貨}了。"}, {"text": "「還要學什麼嗎？」我問阿公。", "rhet": [["懸問", "<span class=\"tp-rq\">還要學什麼嗎？</span>"]]}, {"text": "「不用了，學批貨要過一陣子。你還要讀書嗎？」他回。", "rhet": [["懸問", "<span class=\"tp-rq\">你還要讀書嗎？</span>"]]}, {"text": "「要。」我說。"}, {"text": "他說，記得要幫家裡，要好好賣魚。沒有再提好好讀書。", "cite": "他說，記得要幫家裡，要好好賣魚。沒有再提好好讀書", "mean": "暗示家庭的需要和現實的壓力已超越對學業的追求", "rhet": [["類疊", "<span class=\"tp-rq\">要<b class='rq-hi'>好好</b>賣魚。沒有再提<b class='rq-hi'>好好</b>讀書</span>"]]}, {"text": "他說起我爸，說沒兩句，又不說了。他們叫我要幫家裡，叫我得扶住家，撐住這{n:12|頹敗}的牆。多一個人撐住，一動不動，牆至少不會倒塌，就算不能遮風蔽雨又如何。", "cite": "他們叫我要幫家裡，叫我得扶住家，撐住這頹敗的牆", "mean": "強調家庭的脆弱與需要支持的迫切性", "rhet": [["類疊", "<span class=\"tp-rq\">他們<b class='rq-hi'>叫我</b>要幫家裡，<b class='rq-hi'>叫我</b>得扶住家</span>"]]}, {"text": "爸只記得在每個週五夜晚傳LINE過來，說明早還要工作，叫我早點睡。"}, {"text": "一如往常，就算我已經在學業中找到喜歡的事物，甚至有未來的美好模樣。五專畢業兩年，轉學考了好幾間學校，用五專學歷考了研究所，但爸對這些毫無興趣。他的債務{n:13|縛}住阿公與一整個家。", "cite": "他的債務縛住阿公與一整個家", "mean": "暗示父親債務的存在讓阿公與整個家庭受到影響"}], "notes": [["悶困", "指悶脹不適。悶，空間密閉空氣不流通。困，包圍、圍住。"], ["微生物學", "研究微生物的一門學科，微生物指一類肉眼看不到，要在顯微鏡下才能察覺的生物。"], ["虛耗", "浪費、耗損。"], ["自嘲", "以言辭嘲笑自己。"], ["批貨", "大量採購貨品。"], ["頹敗", "衰落、敗壞。"], ["縛", "原是用繩綑綁，此指拘束、約束。"]], "pian": "第三段：作者上五專、大學後仍應家人要求到魚攤幫忙。父親的賭債讓整個家庭經濟受到綁縛。", "xi": "作者在學業與工作中掙扎，即使已在學業中找到興趣與未來的希望，但因父親的賭債、阿公的期待，讓他不得不支撐起家庭的重擔，對此充滿無奈。", "fan": "", "qa": [["作者的長襪勒緊了腿而形成一圈黑線，像卡在網縫間脫鱗的魚體，象徵什麼？（文意推論）", "象徵作者成為魚販已是不可推託的責任，並且深入體內，成為身體的一部分。"], ["上大學時，作者對魚攤工作已能獨當一面，招呼、買賣、殺魚樣樣都行，只差什麼還沒學習？（擷取訊息）", "批貨。"], ["作者已經在學業中找到喜歡的事物，甚至有未來美好的規劃，是什麼原因讓他必須放棄學業？（擷取訊息）", "因為父親的債務縛住整個家庭，讓他必須放棄自己喜愛的事物，接手家中魚攤的工作。"]], "ask": ["作者<b>當時的感受</b>是什麼？", "讓感受<b>改變</b>的事件是什麼？"], "askT": "<b>第2節 5–18′</b>　逐段提問：<br>· 「作者在哪裡表達了<b>明確</b>感受？」<br>· 「哪個事件可能是理解改變的關鍵？」<br>· 「這個改變是<b>突然</b>發生，還是<b>逐步</b>形成？」"}, {"seg": "第四段", "title": "第四段", "book": "課本 P.14~P.15", "noteStart": 14, "lines": [{"text": "「你要好好讀書，別跟那個哥哥一樣賣魚喔。」站在攤位前，有客人這樣說過。", "cite": "「你要好好讀書，別跟那個哥哥一樣賣魚喔。」站在攤位前，有客人這樣說過", "mean": "一般人對從事勞動工作者存在偏見，暗示賣魚工作不是理想的職業"}, {"text": "「對啊，要好好讀書喔，別像我一樣讀交大喔。」一時嘴賤回了客人，客人就此不再來。", "rhet": [["倒反", "<span class=\"tp-rq\">對啊，要好好讀書喔，別像我一樣讀交大喔</span>"]]}, {"text": "他不知道，我就算好好讀書，還是得賣魚。", "cite": "他不知道，我就算好好讀書，還是得賣魚", "mean": "表達作者對於現實的無奈與掙扎"}, {"text": "在我放棄研究所的那天，我告訴了他，我爸。"}, {"text": "他只說要賣魚，讀那麼高幹麼？", "rhet": [["激問", "<span class=\"tp-rq\">讀那麼高幹麼？</span>"]]}, {"text": "那年過年，我開始學習批貨，不再讀書，忘記自己曾經有過的夢。", "cite": "那年過年，我開始學習批貨，不再讀書，忘記自己曾經有過的夢", "mean": "作者在家庭責任與追求個人理想間，最終選擇放棄自己的夢想"}, {"text": "成了魚販。每天凌晨穿上雨鞋，直到下午，脫下雨鞋與長襪，忽然解放又{n:14|襲來}痠痛，更深更深的睡意。"}, {"text": "我以為洗去身上的魚味，穿上怎樣的服裝，又能變成怎樣的人。但作為魚販，是{n:15|黏著}在皮膚上的魚鱗，沒有感覺便{n:16|嵌}在那，覺得癢的時候想拔下那些魚鱗，才發現體膚已經有不一樣的顏色了。", "cite": "我以為洗去身上的魚味，穿上怎樣的服裝，又能變成怎樣的人", "mean": "希望透過除去身上魚味與改變穿著來讓自己的形象與生活狀態有所不同，暗示對現實的逃避和追求更好生活的期望", "cite2": "但作為魚販，是黏著在皮膚上的魚鱗，沒有感覺便嵌在那，覺得癢的時候想拔下那些魚鱗，才發現體膚已經有不一樣的顏色了", "mean2": "「魚鱗」暗示所承受的負擔，這些負擔隱形的附著在身上，讓作者感到不適卻又無法擺脫"}, {"text": "凌晨兩三點的高速公路，沒什麼車，通往那時最熱鬧的地方：魚市。嘈雜到嗓門加大，氣味紛雜，聞不出魚臭，千百盞燈照出的世界已無黑暗。我下了貨車，踏入潮溼，邊走邊點頭或是捶打他人手臂，幾句髒話，都只是招呼。當我習慣這些生活，我就接受了自己是名魚販。魚販中，有幾個跟我相似的年輕人，有{n:17|老派}如阿公的人；有幾個會讓人想起誰，有幾個是他自己的模樣。", "rhet": [["聽覺摹寫", "<span class=\"tp-rq\">嘈雜到嗓門加大</span>"], ["嗅覺摹寫", "<span class=\"tp-rq\">氣味紛雜，聞不出魚臭</span>"], ["視覺摹寫", "<span class=\"tp-rq\">千百盞燈照出的世界已無黑暗</span>"], ["觸覺摹寫", "<span class=\"tp-rq\">踏入潮溼</span>"]]}, {"text": "「讀那麼高，幹麼賣魚啦？」又有人問我。", "cite": "「讀那麼高，幹麼賣魚啦？」又有人問我。我更難回答了。「只是工作。」我說", "mean": "外界對念過研究所的作者從事賣魚工作產生質疑，作者簡單回應只是工作，反映他對現實的無奈與對自己選擇的辯護"}, {"text": "我更難回答了。「只是工作。」我說。"}], "notes": [["襲來", "撲向、觸及。"], ["黏著", "附著緊貼。"], ["嵌", "把東西填入空隙。"], ["老派", "觀念舉止守舊。"]], "pian": "第四段：作者因家庭因素，放棄高學歷及夢想，成為魚販並接受這個身分。", "xi": "作者放棄高學歷及夢想，還要接受社會世俗質疑的眼光，在家庭責任與個人理想間掙扎，除迷茫、無奈，也充滿遺憾。但回頭檢視時，發覺自己已接受成為魚販的事實。", "fan": "", "qa": [["有客人站在攤位前跟小孩告誡要好好讀書，不要像作者一樣賣魚。社會大眾對賣魚工作抱持什麼想法？（文意推論）", "對魚販工作的不理解與不尊重，並主觀認為不讀書的人才會去賣魚。"], ["作者說：「作為魚販，是黏著在皮膚上的魚鱗，沒有感覺便嵌在那，覺得癢的時候想拔下那些魚鱗，才發現體膚已經有不一樣的顏色了。」這句話意謂什麼？（文意推論）", "意謂魚販的特質在不知不覺間已經深入作者體內，無法改變。"]], "ask": ["作者把魚賣得很好，這代表他已經<b>接受</b>這份工作了嗎？"], "askT": "<b>第2節 30–40′ 主問題。</b><br><span class='ls-warn'>這個問法比「什麼工作才有價值」更貼近課文——它讓學生發現「<b>做得好</b>」和「<b>想做</b>」可以<b>不同時成立</b>。</span><br><br>延伸：「把工作做好」和「必須忍受所有不合理」有什麼不同？"}, {"seg": "第五段", "title": "第五段", "book": "課本 P.16~P.17", "noteStart": 18, "lines": [{"text": "接下魚攤時，吳郭魚一公斤六十元，阿公中風在床。我仍在賣魚，變了一些，但爸仍然在賭。沒人問過我喜不喜歡賣魚，我卻每日每夜的問自己：不喜歡又能怎樣？", "cite": "沒人問過我喜不喜歡賣魚，我卻每日每夜的問自己：不喜歡又能怎樣？", "mean": "反映作者的不滿與無奈。「不喜歡又能怎樣」顯示出他對現實的妥協", "rhet": [["激問", "<span class=\"tp-rq\">不喜歡又能怎樣？</span>"]]}, {"text": "賣魚賣雞賣肉不太會成為志願，也非我志向，非我所願，但要找個支撐住「家」的方法，便是直挺的站著喊：人客來喔，魚很新鮮喔。", "rhet": [["類疊", "<span class=\"tp-rq\">也<b class='rq-hi'>非我</b>志向，<b class='rq-hi'>非我</b>所願</span>"], ["飛白", "<span class=\"tp-rq\">人客來喔，魚很新鮮喔</span>"]]}, {"text": "又幾年後，阿公死去，吳郭魚一公斤七十元，臺灣的白鯧愈來愈少，冷凍的白鯧不復見。我仍然賣魚，但離開了原生家庭，不在魚攤。{n:18|裝睡的人叫不醒}，爸仍然在賭。為了我的兒女，我得離開。", "rhet": [["借喻", "<span class=\"tp-rq\">裝睡的人叫不醒</span>──以「裝睡」喻父親刻意迴避、不願面對的態度。"]], "cite": "裝睡的人叫不醒，爸仍然在賭", "mean": "表達對父親的失望。「裝睡的人叫不醒」暗示父親對家庭問題的逃避與無所作為，無論旁人如何努力，他都不改變自己的行為。「爸仍然在賭」更直接指出父親持續沉迷賭博，家庭所面臨的困境與壓力"}, {"text": "現在我會吃冷凍的白鯧了，我會輕輕的夾給兒女和自己。我們都吃過現流的白鯧，所以知道冷凍白鯧不好吃。", "cite": "現在我會吃冷凍的白鯧了，我會輕輕的夾給兒女和自己。我們都吃過現流的白鯧，所以知道冷凍白鯧不好吃", "mean": "對於冷凍白鯧的接受，暗示在生活中接受現實的過程，也是對過去種種的回憶與懷念。現流的白鯧象徵過去的一切；冷凍白鯧則代表新的生活現實"}, {"text": "變成稱職的魚販之前，我學會了什麼工作令我厭惡，同時學會了什麼令我嚮往。既然不愛的、討厭的都能做好，那還有什麼不能做呢？我這麼想。", "cite": "既然不愛的、討厭的都能做好，那還有什麼不能做呢？", "mean": "在面對生活挑戰時的勇氣與決心", "rhet": [["類疊", "<span class=\"tp-rq\">我<b class='rq-hi'>學會了什麼</b>工作<b class='rq-hi'>令我</b>厭惡，同時<b class='rq-hi'>學會了什麼</b><b class='rq-hi'>令我</b>嚮往</span>"], ["激問", "<span class=\"tp-rq\">那還有什麼不能做呢？</span>"]]}, {"text": "沒有出生就會賣魚的人。沒有什麼東西，不用學一輩子。", "ask": ["同樣一句「賣魚要學」，阿公和爸差在哪<b>三個字</b>？", "這三個字的差別，代表他們怎麼看這份工作？", "作者後來比較像誰？"], "askT": "<b>本課第一個關鍵句。</b><br>阿公當它是<b>一門手藝</b>（學一輩子），爸當它是<b>退路</b>（學一下子）。作者夾在中間。<br><br>可以問：「如果你要接家裡的工作，你希望聽到哪一句？」", "rhet": [["類疊", "<span class=\"tp-rq\"><b class='rq-hi'>沒有</b>出生就會賣魚的人。<b class='rq-hi'>沒有</b>什麼東西</span>"]]}, {"text": "身為一名魚販，我很努力，很努力了。", "cite": "身為一名魚販，我很努力，很努力了", "mean": "重複「很努力」，表示對這個身分的肯定", "rhet": [["類疊", "<span class=\"tp-rq\">我<b class='rq-hi'>很努力</b>，<b class='rq-hi'>很努力</b>了</span>"]]}], "notes": [["裝睡的人叫不醒", "指故意假裝睡覺的人不會因為別人的呼喚而醒來。通常形容人故意不回應或漠不關心的態度。"]], "pian": "第五段：作者敘述成為魚販的心路歷程，完全接受自己已成為一名努力的魚販。", "xi": "從四條支線：阿公的身體狀況、白鯧的價格、自我的成長及父親的惡習來敘述。阿公如白鯧，逐漸消失，家庭的責任也在作者有了兒女而變得沉重，但對於生活的挑戰，不管愛或不愛都要有勇氣，作者在這過程中肯定自己的努力。", "fan": "", "qa": [["為何作者說爸爸是「裝睡的人叫不醒」？（擷取訊息）", "因歷經積欠賭債、阿公過世等巨變，爸爸無視這些狀況還繼續賭博。"], ["是什麼原因讓作者決定離開原生家庭？（擷取訊息）", "因作者的爸爸繼續賭博，作者為了自己的兒女考量，決定離開原生家庭。"]], "ask": ["作者最後<b>和解</b>了嗎？和誰？"], "askT": "<b>第2節 收束。</b><br>照念：「一個人可以對工作有不喜歡的地方，也可以在工作中學到能力。這兩件事<b>不一定互相矛盾</b>。」<br><br>接著轉到第3節：「下一節不再講課文，而是把『用細節呈現經驗』變成自己的寫作方法。」"}]}]);
